/* [project]/src/styles/globals.css [app-client] (css) */
:root {
  --lightningcss-light: initial;
  --lightningcss-dark: ;
  color-scheme: light dark;
  --paper: var(--lightningcss-light, #f3f3ef) var(--lightningcss-dark, #131a20);
  --panel: var(--lightningcss-light, #fbfbf9) var(--lightningcss-dark, #1d272f);
  --board: var(--lightningcss-light, #ebebe6) var(--lightningcss-dark, #182128);
  --line: var(--lightningcss-light, #dbdbd3) var(--lightningcss-dark, #313d47);
  --ink: var(--lightningcss-light, #22303a) var(--lightningcss-dark, #e2e5e0);
  --ink-2: var(--lightningcss-light, #5d6c77) var(--lightningcss-dark, #9ba7b0);
  --ink-3: var(--lightningcss-light, #98a3ab) var(--lightningcss-dark, #6b7984);
  --status-1: var(--lightningcss-light, #c9d4f1) var(--lightningcss-dark, #4f64a3);
  --status-2: var(--lightningcss-light, #6e86d0) var(--lightningcss-dark, #7189d8);
  --status-3: var(--lightningcss-light, #1e3e9e) var(--lightningcss-dark, #a9bbf6);
  --accent: var(--lightningcss-light, #1e3e9e) var(--lightningcss-dark, #9db0f3);
  --ui: var(--font-instrument-sans), "Instrument Sans", system-ui, sans-serif;
  --read: var(--font-newsreader), "Newsreader", Georgia, serif;
  --focus-ring: 2px solid var(--accent);
  --ease-standard: cubic-bezier(.2, .8, .2, 1);
  --ease-entrance: cubic-bezier(.16, 1, .3, 1);
  --ease-exit: cubic-bezier(.4, 0, 1, 1);
  --ease-spring: cubic-bezier(.34, 1.3, .64, 1);
  --dur-instant: 80ms;
  --dur-quick: .13s;
  --dur-standard: .22s;
  --dur-move: .38s;
  --dur-leave: .17s;
  --dur-calm: 1.25s;
  --lift: 2px;
  --press-scale: .985;
  --enter-travel: 8px;
  --surface-page: var(--paper);
  --surface-panel: var(--panel);
  --surface-board: var(--board);
  --surface-float: var(--lightningcss-light, var(--panel)) var(--lightningcss-dark, #232e37);
  --scrim: var(--lightningcss-light, #22303a2e) var(--lightningcss-dark, #04080b73);
  --scrim-dialog: var(--lightningcss-light, #22303a47) var(--lightningcss-dark, #04080b99);
  --scrim-blur: var(--lightningcss-light, #f3f3efb8) var(--lightningcss-dark, #131a20cc);
  --text: var(--ink);
  --text-muted: var(--ink-2);
  --text-decor: var(--ink-3);
  --rule: var(--line);
  --shade: var(--lightningcss-light, #22303a) var(--lightningcss-dark, #000);
  --shadow-pic: 0 1px 2px var(--lightningcss-light, #22303a12) var(--lightningcss-dark, #00000052), 0 8px 22px var(--lightningcss-light, #22303a17) var(--lightningcss-dark, #00000042);
  --shadow-lift: 0 2px 4px var(--lightningcss-light, #22303a14) var(--lightningcss-dark, #00000057), 0 16px 36px var(--lightningcss-light, #22303a26) var(--lightningcss-dark, #0006);
  --shadow-float: 0 0 0 1px var(--lightningcss-light, #0000) var(--lightningcss-dark, #ffffff0d), 0 1px 2px var(--lightningcss-light, #22303a0f) var(--lightningcss-dark, #0000), 0 18px 48px var(--lightningcss-light, #22303a29) var(--lightningcss-dark, #0000006b);
  --shadow-mark: 0 3px 5px var(--lightningcss-light, #22303a38) var(--lightningcss-dark, #00000080);
  --shadow-lane: 0 4px 8px var(--lightningcss-light, #22303a1a) var(--lightningcss-dark, #00000059);
  --shadow-rail: 10px 0 30px var(--lightningcss-light, #22303a14) var(--lightningcss-dark, #00000059);
  --accent-soft: var(--lightningcss-light, #e6ebf8) var(--lightningcss-dark, #263156);
  --accent-strong: var(--lightningcss-light, #142b73) var(--lightningcss-dark, #c3cff8);
  --warn: var(--lightningcss-light, #9a3b2e) var(--lightningcss-dark, #ec9c8d);
  --warn-soft: var(--lightningcss-light, #f6e4df) var(--lightningcss-dark, #3a2521);
  --ok: var(--lightningcss-light, #2f6b4a) var(--lightningcss-dark, #84c9a2);
  --quote-paper: var(--lightningcss-light, #faf8f2) var(--lightningcss-dark, #29271f);
  --quote-rule: var(--lightningcss-light, #eae5d9) var(--lightningcss-dark, #3f3a2e);
  --note-paper: var(--lightningcss-light, #faf9f5) var(--lightningcss-dark, #21282c);
  --hover-fill: var(--lightningcss-light, #ecece6) var(--lightningcss-dark, #2a353f);
  --ghost: var(--lightningcss-light, #7b8fd4) var(--lightningcss-dark, #8497dc);
  --ghost-soft: var(--lightningcss-light, #7b8fd414) var(--lightningcss-dark, #8497dc1a);
  --ghost-ink: var(--lightningcss-light, #4a5fa8) var(--lightningcss-dark, #b3c1f0);
  --myfocus-ink: var(--lightningcss-light, #8a5a00) var(--lightningcss-dark, #e8c27a);
  --myfocus-paper: var(--lightningcss-light, #fbf3df) var(--lightningcss-dark, #33291a);
  --myfocus-rule: var(--lightningcss-light, #ecd9a8) var(--lightningcss-dark, #5a4824);
  --attention-ink: var(--myfocus-ink);
  --attention-paper: var(--myfocus-paper);
  --entity-work: var(--lightningcss-light, #1f6e43) var(--lightningcss-dark, #84c9a2);
  --entity-work-strong: var(--lightningcss-light, #154c2e) var(--lightningcss-dark, #a8dcbe);
  --entity-work-tint: var(--lightningcss-light, #2a7a4e) var(--lightningcss-dark, #84c9a2);
  --on-ink: var(--lightningcss-light, #fff) var(--lightningcss-dark, #131a20);
  --on-accent: var(--lightningcss-light, #fff) var(--lightningcss-dark, #131a20);
  --surface-over-page: var(--lightningcss-light, #0000) var(--lightningcss-dark, #232e37);
  --surface-mat: var(--lightningcss-light, #e4e4de) var(--lightningcss-dark, #0d1317);
  --on-media: #fff;
  --media-badge: #000000ad;
  --caption-bg: #ecece9f0;
  --caption-ink: #1f1f1d;
  --media-control: #ffffffeb;
  --cover-paper: #202e38;
  --cover-ink: #edeff6;
  --cover-line: #ffffff12;
  --cover-spine-light: #ffffff1c;
  --cover-spine-shade: #00000061;
  --page-paper: #fff;
  --page-ink: #1d262d;
  --page-ink-2: #6b757c;
  --page-select: #f6dc8f;
  --page-mark: #fbeec2;
  --page-night: invert(.9) hue-rotate(180deg);
  --m-bar: calc(52px + env(safe-area-inset-top, 0px));
  --m-tabs: calc(56px + env(safe-area-inset-bottom, 0px));
  --m-gutter: 16px;
  --m-hit: 44px;
  --m-peek: 132px;
  --m-sheet-radius: 14px;
  --m-kb: 0px;
  --t-rail: 58px;
  --t-panel: clamp(360px, 32vw, 420px);
  --t-sheet-w: 584px;
}

@media (prefers-color-scheme: dark) {
  :root {
    --lightningcss-light: ;
    --lightningcss-dark: initial;
  }
}

@media (pointer: coarse) {
  :root {
    --t-rail: 72px;
  }
}

:root[data-theme="light"] {
  --lightningcss-light: initial;
  --lightningcss-dark: ;
  color-scheme: light;
}

:root[data-theme="dark"] {
  --lightningcss-light: ;
  --lightningcss-dark: initial;
  color-scheme: dark;
}

@media (prefers-reduced-motion: reduce) {
  :root {
    --dur-instant: 1ms;
    --dur-quick: 1ms;
    --dur-standard: 1ms;
    --dur-move: 1ms;
    --dur-leave: 1ms;
    --dur-calm: 1ms;
  }
}

:root {
  --rail-w: var(--t-rail);
}

@media (min-width: 700px) and (pointer: fine) {
  :root:has(.app-shell[data-rail="open"]) {
    --rail-w: 196px;
  }
}

.app-shell {
  grid-template-columns: var(--rail-w) minmax(0, 1fr);
  background: var(--paper);
  height: 100dvh;
  min-height: 0;
  transition: grid-template-columns var(--dur-standard) var(--ease-standard);
  display: grid;
  overflow: hidden;
}

.skip-link {
  z-index: 200;
  background: var(--ink);
  color: var(--on-ink);
  padding: 8px 12px;
  text-decoration: none;
  position: fixed;
  top: 8px;
  left: 8px;
  transform: translateY(-160%);
}

.skip-link:focus {
  transform: translateY(0);
}

.navigation-rail {
  z-index: 20;
  width: var(--rail-w);
  height: 100dvh;
  position: relative;
}

.rail-in {
  width: var(--rail-w);
  border-right: 1px solid var(--line);
  background: var(--paper);
  transition: width var(--dur-standard) var(--ease-standard);
  flex-direction: column;
  gap: 2px;
  padding: 14px 9px;
  display: flex;
  position: absolute;
  inset: 0 auto 0 0;
  overflow: hidden;
}

.rail-label {
  opacity: 0;
  transition: opacity var(--dur-quick) ease;
}

.app-shell[data-rail="open"] .rail-label {
  opacity: 1;
}

@media (min-width: 700px) and (pointer: coarse) {
  .app-shell {
    grid-template-columns: var(--t-rail) minmax(0, 1fr);
  }

  .navigation-rail, .rail-in {
    width: var(--t-rail);
  }

  .rail-in {
    padding: 12px 6px calc(12px + env(safe-area-inset-bottom, 0px));
  }

  .rail-in .brand-row {
    justify-content: center;
    padding: 0;
  }

  .rail-in .brand-row .brand {
    display: none;
  }

  .rail-in .navigation-link, .rail-in .capture-shortcut {
    flex-direction: column;
    justify-content: center;
    gap: 4px;
    width: 100%;
    height: 56px;
    padding: 0;
  }

  .rail-in .navigation-link .rail-label, .rail-in .capture-shortcut .rail-label {
    opacity: 1;
    white-space: normal;
    text-align: center;
    font-size: 11.5px;
    font-weight: 550;
    line-height: 1.1;
  }

  .rail-in .account-trigger {
    justify-content: center;
    height: 48px;
  }

  .rail-in .account-name, .rail-in .rail-toggle {
    display: none;
  }
}

@media (min-width: 700px) and (pointer: coarse) and (max-height: 599.98px) {
  .rail-in {
    gap: 0;
    padding-top: 8px;
    overflow-y: auto;
  }

  .rail-in .brand-row {
    height: 30px;
    margin-bottom: 4px;
  }

  .rail-in .navigation-link, .rail-in .capture-shortcut, .rail-in .theme-toggle, .rail-in .account-trigger {
    height: 44px;
  }

  .rail-in .navigation-link .rail-label, .rail-in .capture-shortcut .rail-label {
    display: none;
  }
}

.brand-row {
  height: 34px;
  color: var(--ink);
  white-space: nowrap;
  border-radius: 4px;
  align-items: center;
  gap: 10px;
  margin: 0 0 14px;
  padding: 0 5px;
  text-decoration: none;
  display: flex;
}

.brand-row:focus-visible {
  outline: var(--focus-ring);
  outline-offset: -2px;
}

.brand-mark {
  background: var(--ink);
  width: 30px;
  height: 30px;
  color: var(--on-ink);
  font-family: var(--read);
  border-radius: 7px;
  flex: 0 0 30px;
  place-items: center;
  font-size: 18px;
  display: grid;
}

.brand {
  letter-spacing: 0;
  margin: 0;
  font-size: 16px;
  font-weight: 600;
}

.capture-shortcut, .navigation-link {
  box-sizing: border-box;
  height: 36px;
  color: var(--ink-2);
  cursor: pointer;
  font: inherit;
  white-space: nowrap;
  background: none;
  border: 0;
  border-radius: 4px;
  align-items: center;
  gap: 12px;
  padding: 0 11px;
  font-size: 13.5px;
  text-decoration: none;
  display: flex;
}

.capture-shortcut svg, .navigation-link svg {
  flex: none;
}

.capture-shortcut {
  color: var(--accent);
  margin-bottom: 8px;
}

.capture-shortcut:hover, .navigation-link:hover {
  background: var(--hover-fill);
  color: var(--ink);
}

.capture-shortcut:hover {
  color: var(--accent);
}

.capture-shortcut:focus-visible, .navigation-link:focus-visible, .account-trigger:focus-visible {
  outline: var(--focus-ring);
  outline-offset: -2px;
}

.primary-links, .theme-links {
  gap: 2px;
  display: grid;
}

.theme-links {
  margin-top: auto;
}

.rail-toggle, .theme-toggle {
  text-align: left;
  width: 100%;
}

.theme-toggle-to-light {
  display: none;
}

.theme-toggle-to-dark {
  display: flex;
}

.theme-toggle-to-dark, .theme-toggle-to-light {
  align-items: center;
  gap: 12px;
}

:root[data-theme="dark"] .theme-toggle-to-dark {
  display: none;
}

:root[data-theme="dark"] .theme-toggle-to-light {
  display: flex;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme]) .theme-toggle-to-dark {
    display: none;
  }

  :root:not([data-theme]) .theme-toggle-to-light {
    display: flex;
  }
}

.navigation-link[aria-current="page"] {
  background: var(--panel);
  box-shadow: inset 0 0 0 1px var(--line);
  color: var(--ink);
}

.account-menu {
  min-width: 0;
  margin-top: 8px;
}

.account-trigger {
  width: 100%;
  min-width: 0;
  color: var(--ink);
  cursor: pointer;
  text-align: left;
  white-space: nowrap;
  background: none;
  border: 0;
  border-radius: 4px;
  align-items: center;
  gap: 10px;
  padding: 5px 7px;
  display: flex;
}

.account-trigger:hover, .account-trigger[data-state="open"] {
  background: var(--panel);
  box-shadow: inset 0 0 0 1px var(--line);
}

.account-avatar {
  border: 1px solid var(--line);
  background: var(--board);
  width: 26px;
  height: 26px;
  color: var(--accent);
  border-radius: 50%;
  flex: 0 0 26px;
  place-items: center;
  font-size: 11px;
  font-weight: 600;
  display: grid;
}

.account-name {
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 13px;
  font-weight: 500;
  overflow: hidden;
}

.account-menu-content {
  z-index: 40;
  background: var(--surface-float);
  width: 248px;
  min-width: 144px;
  max-width: calc(100vw - 18px);
  box-shadow: var(--shadow-float), inset 0 0 0 1px var(--rule);
  border-radius: 4px;
  padding: 4px;
}

.account-menu-item {
  width: 100%;
  color: var(--ink);
  cursor: pointer;
  border-radius: 3px;
  align-items: center;
  gap: 8px;
  padding: 7px 10px;
  font-size: 13px;
  text-decoration: none;
  display: flex;
}

.account-menu-item[data-highlighted] {
  background: var(--hover-fill);
  outline: none;
}

.account-menu-item svg {
  color: var(--ink-2);
  flex: none;
}

.account-menu-error {
  color: var(--warn);
  margin: 4px 10px 6px;
  font-size: 12px;
  line-height: 1.35;
}

.appearance {
  border-top: 1px solid var(--rule);
  border-bottom: 1px solid var(--rule);
  margin: 4px 0;
  padding: 8px 10px 10px;
}

.appearance-head {
  color: var(--text-muted);
  justify-content: space-between;
  align-items: baseline;
  margin: 0 0 7px;
  font-size: 12px;
  display: flex;
}

.appearance-head b {
  color: var(--text);
  font-size: 13px;
  font-weight: 500;
}

.appearance-seg {
  background: var(--surface-page);
  box-shadow: inset 0 0 0 1px var(--rule);
  border-radius: 4px;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  padding: 3px;
  display: grid;
  position: relative;
}

.appearance-option {
  z-index: 1;
  color: var(--text-muted);
  text-align: center;
  cursor: pointer;
  border-radius: 3px;
  outline: none;
  padding: 5px 4px;
  font-size: 12.5px;
  position: relative;
}

.appearance-option[data-state="checked"] {
  color: var(--text);
  font-weight: 500;
}

.appearance-option[data-highlighted] {
  outline: var(--focus-ring);
  outline-offset: -1px;
}

.appearance-thumb {
  z-index: 0;
  background: var(--surface-float);
  width: calc(33.3333% - 2px);
  box-shadow: var(--shadow-pic), inset 0 0 0 1px var(--rule);
  transition: transform var(--dur-standard) var(--ease-standard);
  border-radius: 3px;
  position: absolute;
  top: 3px;
  bottom: 3px;
  left: 3px;
}

.appearance-note {
  color: var(--text-muted);
  margin-top: 6px;
  font-size: 11.5px;
  display: block;
}

.main-stage {
  overscroll-behavior: contain;
  scrollbar-gutter: stable;
  min-width: 0;
  height: 100dvh;
  padding: 36px 44px 52px;
  overflow-y: auto;
}

.destination-header {
  border-bottom: 1px solid var(--line);
  margin: -4px 0 30px;
}

.destination-crumb {
  min-height: 16px;
  color: var(--ink-2);
  flex-wrap: wrap;
  align-items: center;
  gap: 7px;
  margin: 0 0 12px;
  font-size: 12.5px;
  display: flex;
}

.destination-crumb strong {
  color: var(--ink);
  font-weight: 500;
}

.destination-tabs {
  align-items: flex-end;
  gap: 2px;
  margin-bottom: -1px;
  display: flex;
  overflow-x: auto;
}

.destination-tab {
  color: var(--ink-2);
  white-space: nowrap;
  border-bottom: 2px solid #0000;
  flex: none;
  padding: 7px 12px 9px;
  font-size: 13.5px;
  text-decoration: none;
}

.destination-tab:hover {
  color: var(--ink);
}

.destination-tab[aria-current="page"] {
  border-bottom-color: var(--accent);
  color: var(--ink);
  font-weight: 500;
}

.button {
  background: var(--accent);
  min-height: 36px;
  color: var(--on-accent);
  cursor: pointer;
  border: 0;
  border-radius: 2px;
  justify-content: center;
  align-items: center;
  gap: 8px;
  padding: 8px 14px;
  font-weight: 500;
  display: inline-flex;
}

.button-quiet {
  box-shadow: inset 0 0 0 1px var(--line);
  color: var(--ink);
  background: none;
}

.button-danger {
  box-shadow: inset 0 0 0 1px var(--warn);
  color: var(--warn);
}

.button-link {
  min-height: 0;
  color: var(--ink-2);
  background: none;
  padding: 8px 2px;
  font-weight: 400;
}

.button:disabled, .button[aria-disabled="true"] {
  cursor: not-allowed;
  opacity: .56;
}

.field {
  gap: 6px;
  display: grid;
}

.field-label {
  font-size: 13px;
  font-weight: 500;
}

.field-control {
  border: 1px solid var(--line);
  background: var(--panel);
  width: 100%;
  min-height: 40px;
  color: var(--ink);
  border-radius: 2px;
  padding: 9px 11px;
}

.field-hint {
  color: var(--ink-2);
  margin: 0;
  font-size: 12px;
}

.notice {
  border-left: 2px solid var(--accent);
  background: var(--panel);
  color: var(--ink-2);
  padding: 13px 15px;
}

.notice strong {
  color: var(--ink);
  margin-bottom: 3px;
  font-weight: 600;
  display: block;
}

.workspace-status {
  color: var(--ink-2);
  margin: 0;
  padding: 36px 44px;
}

.workspace-panel, .preferences-form {
  width: min(100%, 680px);
}

.workspace-panel {
  border: 1px solid var(--line);
  background: var(--panel);
  padding: 24px;
}

.workspace-kicker {
  color: var(--accent);
  text-transform: capitalize;
  margin: 0 0 10px;
  font-size: 12px;
  font-weight: 600;
}

.workspace-panel h1, .preferences-form h1 {
  font-family: var(--read);
  margin: 0 0 8px;
  font-size: 27px;
  font-weight: 500;
  line-height: 1.2;
}

.workspace-panel p, .preferences-form-heading p {
  color: var(--ink-2);
  margin: 0;
}

.workspace-reference {
  font-family: ui-monospace, monospace;
  font-size: 12px;
  margin-top: 12px !important;
}

.preferences-form {
  gap: 18px;
  display: grid;
}

.preferences-form-heading {
  margin-bottom: 8px;
}

.preferences-conflict {
  border: 1px solid var(--line);
  border-left: 2px solid var(--accent);
  background: var(--panel);
  gap: 14px;
  padding: 18px;
  display: grid;
}

.preferences-conflict h2 {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
}

.preferences-conflict dl {
  gap: 8px;
  margin: 0;
  display: grid;
}

.preferences-conflict dl div {
  grid-template-columns: 130px minmax(0, 1fr);
  gap: 12px;
  display: grid;
}

.preferences-conflict dt, .preferences-conflict dd {
  overflow-wrap: anywhere;
  margin: 0;
}

.preferences-conflict dt {
  color: var(--ink-2);
  font-size: 13px;
}

.preferences-actions {
  flex-wrap: wrap;
  gap: 10px;
  display: flex;
}

.specimen-intro {
  max-width: 64ch;
  margin-bottom: 28px;
}

.specimen-intro h1 {
  font-family: var(--read);
  margin: 0 0 8px;
  font-size: 30px;
  font-weight: 500;
  line-height: 1.2;
}

.specimen-intro p {
  color: var(--ink-2);
  margin: 0;
}

.specimen-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 18px;
  margin-bottom: 28px;
  display: grid;
}

.specimen-card {
  background: var(--panel);
  min-height: 176px;
  box-shadow: inset 0 0 0 1px var(--line);
  flex-direction: column;
  gap: 8px;
  padding: 18px 18px 14px;
  display: flex;
}

.specimen-card small {
  color: var(--ink-2);
  font-size: 11.5px;
}

.specimen-card h2 {
  font-family: var(--read);
  margin: 0;
  font-size: 19px;
  font-weight: 400;
  line-height: 1.25;
}

.specimen-card p {
  color: var(--ink-2);
  margin: 0;
  font-size: 13px;
}

.specimen-actions {
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  display: flex;
}

.tab-bar, html[data-keyboard] .tab-bar {
  display: none;
}

.specimen-notice {
  margin-top: 24px;
}

@media (max-width: 980px) {
  .main-stage {
    padding: 28px 24px 40px;
  }

  .workspace-status {
    padding: 28px 24px;
  }

  .specimen-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 699.98px) {
  .app-shell {
    height: auto;
    min-height: 100dvh;
    display: block;
    overflow: visible;
  }

  .navigation-rail {
    z-index: 40;
    width: 100%;
    height: var(--m-bar);
    min-height: 0;
    padding: env(safe-area-inset-top, 0px) 6px 0 var(--m-gutter);
    box-sizing: border-box;
    border-bottom: 1px solid var(--line);
    align-items: center;
    gap: 2px;
    display: flex;
    position: sticky;
    top: 0;
  }

  @supports (color: color-mix(in lab, red, red)) {
    .navigation-rail {
      border-bottom: 1px solid color-mix(in srgb, var(--line) 70%, transparent);
    }
  }

  .navigation-rail:before {
    content: "";
    z-index: -1;
    background: var(--paper);
    position: absolute;
    inset: 0;
  }

  @supports (color: color-mix(in lab, red, red)) {
    .navigation-rail:before {
      background: color-mix(in srgb, var(--paper) 80%, transparent);
    }
  }

  .navigation-rail:before {
    -webkit-backdrop-filter: blur(20px) saturate(160%);
    backdrop-filter: blur(20px) saturate(160%);
  }

  .rail-in {
    display: contents;
  }

  .rail-label {
    opacity: 1;
  }

  .navigation-rail .primary-links, .theme-links {
    display: none;
  }

  .brand-row {
    flex: auto;
    gap: 8px;
    height: auto;
    margin: 0;
    padding: 0;
  }

  .brand-row .brand-mark {
    width: 26px;
    height: 26px;
  }

  .brand-row .brand {
    letter-spacing: -.01em;
    font-size: 16px;
    font-weight: 600;
  }

  .capture-shortcut {
    width: var(--m-hit);
    height: var(--m-hit);
    flex: 0 0 var(--m-hit);
    box-shadow: none;
    background: none;
    border-radius: 50%;
    justify-content: center;
    margin: 0;
    padding: 0;
    position: relative;
  }

  .capture-shortcut:before {
    content: "";
    box-shadow: inset 0 0 0 1.5px var(--accent);
    border-radius: 50%;
    position: absolute;
    inset: 8px;
  }

  .capture-shortcut svg {
    width: 16px;
    height: 16px;
    color: var(--accent);
  }

  .capture-shortcut .rail-label {
    display: none;
  }

  .account-menu {
    margin: 0;
    position: static;
  }

  .account-trigger {
    width: var(--m-hit);
    height: var(--m-hit);
    justify-content: center;
    padding: 0;
  }

  .account-name {
    display: none;
  }

  .tab-bar {
    z-index: 42;
    height: var(--m-tabs);
    padding: 0 0 env(safe-area-inset-bottom, 0px);
    box-sizing: border-box;
    border-top: 1px solid var(--line);
    grid-template-columns: repeat(4, 1fr);
    display: grid;
    position: fixed;
    bottom: 0;
    left: 0;
    right: 0;
  }

  @supports (color: color-mix(in lab, red, red)) {
    .tab-bar {
      border-top: 1px solid color-mix(in srgb, var(--line) 70%, transparent);
    }
  }

  .tab-bar {
    background: var(--paper);
  }

  @supports (color: color-mix(in lab, red, red)) {
    .tab-bar {
      background: color-mix(in srgb, var(--paper) 80%, transparent);
    }
  }

  .tab-bar {
    -webkit-backdrop-filter: blur(20px) saturate(160%);
    backdrop-filter: blur(20px) saturate(160%);
  }

  .tab-bar-link {
    letter-spacing: .01em;
    height: 56px;
    color: var(--ink-2);
    flex-direction: column;
    justify-content: center;
    align-items: center;
    gap: 3px;
    font-size: 11.5px;
    font-weight: 550;
    text-decoration: none;
    display: flex;
    position: relative;
  }

  .tab-bar-link[aria-current="page"] {
    color: var(--accent);
  }

  .tab-bar-link[aria-current="page"]:before {
    content: "";
    background: var(--accent);
    width: 28px;
    height: 2px;
    position: absolute;
    top: 0;
  }

  .tab-bar-link:focus-visible {
    outline: var(--focus-ring);
    outline-offset: -2px;
  }

  .main-stage {
    height: auto;
    min-height: calc(100dvh - var(--m-bar));
    padding: 16px var(--m-gutter) calc(var(--m-tabs) + 28px);
    overflow: visible;
  }

  .workspace-status {
    padding: 20px var(--m-gutter);
  }

  .specimen-grid {
    grid-template-columns: 1fr;
  }

  .preferences-conflict dl div {
    grid-template-columns: 1fr;
    gap: 2px;
  }

  html {
    -webkit-tap-highlight-color: transparent;
  }

  .button:active:not(:disabled), .tab-bar-link:active, .destination-tab:active, .account-trigger:active, .capture-shortcut:active {
    transition: transform .1s ease-out;
    transform: scale(.97);
  }
}

@media (max-width: 699.98px), (pointer: coarse) {
  input:not([type="checkbox"]):not([type="radio"]):not([type="range"]), textarea, select {
    font-size: max(16px, 1em) !important;
  }
}

@media (max-width: 699.98px) and (prefers-reduced-transparency: reduce) {
  .navigation-rail:before, .tab-bar {
    background: var(--paper);
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }
}

@media (max-width: 699.98px) and (prefers-contrast: more) {
  .navigation-rail:before, .tab-bar {
    background: var(--paper);
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }

  .navigation-rail, .tab-bar {
    border-color: var(--ink-2);
  }
}

@media (prefers-reduced-motion: reduce) {
  *, :before, :after {
    scroll-behavior: auto !important;
    transition-duration: .01ms !important;
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
  }
}

.destination-crumb i {
  color: var(--text-muted);
  font-size: 11px;
  font-style: normal;
}

.destination-crumb span {
  color: var(--ink-2);
}

.consent-notice {
  z-index: 40;
  box-sizing: border-box;
  background: var(--surface-float);
  box-shadow: var(--shadow-float);
  color: var(--text);
  border-radius: 10px;
  align-items: flex-start;
  gap: 12px;
  padding: 12px 14px;
  font-size: 13px;
  line-height: 1.45;
  display: flex;
}

.consent-notice-icon {
  background: var(--accent-soft);
  width: 30px;
  height: 30px;
  color: var(--accent);
  border-radius: 50%;
  flex-shrink: 0;
  place-items: center;
  display: grid;
}

.consent-notice-text {
  flex: 1;
  min-width: 0;
}

.consent-notice-text strong {
  margin-bottom: 1px;
  font-size: 13.5px;
  font-weight: 600;
  display: block;
}

.consent-notice-text p {
  color: var(--text-muted);
  margin: 0;
}

.consent-notice-actions {
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  display: flex;
}

.consent-notice .consent-notice-actions .button:not(.button-link) {
  border-radius: 2px;
  min-height: 32px;
  padding: 4px 14px;
  font-size: 13px;
}

.consent-notice .consent-notice-actions .button:not(.button-quiet):hover {
  background: var(--accent-strong);
}

.consent-notice .consent-notice-actions .button-quiet:hover {
  box-shadow: inset 0 0 0 1px var(--text-decor);
  background: var(--hover-fill);
}

.consent-notice .button:focus-visible, .consent-notice-link:focus-visible {
  outline: var(--focus-ring);
  outline-offset: 2px;
}

.consent-notice-link {
  color: var(--text-muted);
  text-underline-offset: 3px;
  white-space: nowrap;
  margin-left: 4px;
  font-size: 12.5px;
  text-decoration: underline;
}

.consent-notice-stage {
  bottom: 48px;
  left: calc(var(--rail-w) + (100vw - var(--rail-w)) / 2);
  width: min(640px, calc(100vw - var(--rail-w) - 32px));
  align-items: center;
  position: fixed;
  translate: -50%;
}

.consent-notice-stage .consent-notice-text {
  padding-right: 6px;
}

@media (min-width: 980.02px) {
  body:has(.cpwrap:not(.is-folded):not(.is-reading)) .consent-notice-stage {
    left: calc(var(--rail-w) + (100vw - var(--rail-w) - var(--t-panel) - 12px) / 2);
    width: min(640px, calc(100vw - var(--rail-w) - var(--t-panel) - 12px - 32px));
  }
}

.consent-notice-column {
  flex-wrap: wrap;
  width: min(420px, 100% - 2 * clamp(40px, 7vw, 110px));
  position: absolute;
  bottom: 24px;
  left: clamp(40px, 7vw, 110px);
}

.consent-notice-column .consent-notice-actions {
  width: 100%;
  padding-left: 42px;
}

@media (max-width: 699.98px) {
  .consent-notice-stage {
    right: 10px;
    bottom: calc(var(--m-tabs) + 10px);
    flex-wrap: wrap;
    width: auto;
    position: fixed;
    left: 10px;
    translate: none;
  }

  .consent-notice-stage .consent-notice-actions {
    width: 100%;
    padding-left: 0;
  }

  .consent-notice-stage .consent-notice-actions .button {
    flex: 1;
  }

  .consent-notice-column {
    flex-wrap: wrap;
    width: auto;
    position: fixed;
    bottom: 10px;
    left: 10px;
    right: 10px;
    translate: none;
  }

  .consent-notice-column .consent-notice-actions {
    width: 100%;
    padding-left: 0;
  }

  .consent-notice-column .consent-notice-actions .button {
    flex: 1;
  }
}

@media (prefers-reduced-motion: no-preference) {
  .consent-notice {
    animation: consent-in .38s var(--ease-spring) both;
  }

  .consent-notice .button {
    transition: background var(--dur-quick), box-shadow var(--dur-quick);
  }
}

@keyframes consent-in {
  from {
    opacity: 0;
    transform: translateY(12px);
  }

  to {
    opacity: 1;
    transform: none;
  }
}

.privacy-toggle {
  align-items: center;
  gap: 8px;
  display: flex;
}

.privacy-note {
  color: var(--ink-2);
  margin: 0;
  font-size: 13px;
}

.privacy-setting h2 {
  font-family: var(--read);
  margin: 0 0 8px;
  font-size: 20px;
  font-weight: 500;
  line-height: 1.2;
}

.privacy-note a {
  color: var(--accent);
  text-underline-offset: 2px;
  text-decoration: underline;
}

.auth {
  background: var(--surface-page);
  min-height: 100dvh;
  color: var(--text);
  grid-template-columns: minmax(0, 1.15fr) minmax(0, 1fr);
  font-size: 14px;
  line-height: 1.5;
  display: grid;
}

.auth-board {
  background: var(--surface-board);
  border-radius: 10px;
  margin: 16px 0 16px 16px;
  position: relative;
  overflow: hidden;
}

.auth-board svg {
  width: 100%;
  height: 78%;
  position: absolute;
  top: 0;
  left: 0;
}

.auth-ring {
  fill: none;
  stroke: var(--rule);
  stroke-dasharray: 2 5;
}

.auth-lk {
  stroke: var(--rule);
  stroke-width: 1px;
}

.auth-lk-g {
  stroke: var(--ghost);
  stroke-dasharray: 3 4;
  stroke-width: 1.2px;
}

.auth-nd {
  fill: var(--surface-page);
  stroke: var(--text-decor);
  stroke-width: 1px;
}

.auth-nd-g {
  fill: var(--ghost-soft);
  stroke: var(--ghost);
  stroke-width: 1.5px;
  stroke-dasharray: 3 3;
}

.auth-ctr {
  fill: var(--text);
  stroke: var(--surface-page);
  stroke-width: 2px;
}

.auth-lbl {
  font-family: var(--ui);
  fill: var(--text-muted);
  text-anchor: middle;
  paint-order: stroke;
  stroke: var(--surface-board);
  stroke-width: 5px;
  stroke-linejoin: round;
}

.auth-lbl-area {
  font-family: var(--read);
  fill: var(--text);
  font-weight: 500;
}

.auth-lbl-g {
  fill: var(--ghost-ink);
  font-style: italic;
}

.auth-lbl-ctr {
  font-family: var(--read);
  fill: var(--text);
}

.auth-mini {
  background: var(--surface-float);
  width: 236px;
  box-shadow: var(--shadow-float);
  border-radius: 8px;
  flex-direction: column;
  gap: 8px;
  padding: 12px;
  font-size: 12px;
  display: flex;
  position: absolute;
  top: 40px;
  right: 34px;
}

.auth-mini-me {
  background: var(--accent-soft);
  border-radius: 10px 10px 2px;
  align-self: flex-end;
  max-width: 86%;
  padding: 6px 9px;
}

.auth-mini small {
  color: var(--text-muted);
  margin-bottom: 2px;
  font-size: 10.5px;
  display: block;
}

.auth-caption {
  position: absolute;
  bottom: 40px;
  left: 40px;
  right: 40px;
}

.auth-caption-lines {
  align-items: end;
  display: grid;
}

.auth-caption-q {
  opacity: 0;
  max-width: 20ch;
  font-family: var(--read);
  letter-spacing: -.01em;
  grid-area: 1 / 1;
  margin: 0;
  font-size: 30px;
  line-height: 1.15;
}

.auth-caption-q.on {
  opacity: 1;
}

.auth-caption-q i {
  color: var(--accent);
}

.auth-dots {
  gap: 6px;
  margin-top: 16px;
  display: flex;
}

.auth-dots i {
  background: var(--text-decor);
  opacity: .45;
  border-radius: 3px;
  width: 6px;
  height: 6px;
}

.auth-dots i.on {
  background: var(--text);
  opacity: 1;
  width: 18px;
}

.auth-form-col {
  flex-direction: column;
  justify-content: center;
  padding: 80px clamp(40px, 7vw, 110px);
  display: flex;
  position: relative;
}

.auth-top {
  align-items: center;
  gap: 12px;
  display: flex;
  position: absolute;
  top: 30px;
  left: clamp(40px, 7vw, 110px);
  right: 28px;
}

.auth-wordmark {
  align-items: center;
  gap: 10px;
  margin-right: auto;
  font-size: 17px;
  font-weight: 600;
  display: flex;
}

.auth-mark {
  background: var(--text);
  width: 30px;
  height: 30px;
  color: var(--surface-page);
  font-family: var(--read);
  border-radius: 7px;
  flex-shrink: 0;
  place-items: center;
  font-size: 19px;
  display: grid;
}

.auth-inner {
  flex-direction: column;
  gap: 16px;
  width: 100%;
  max-width: 380px;
  display: flex;
}

.auth-inner-wide {
  max-width: 520px;
}

.auth-inner-wide p {
  margin: 0;
}

.auth-inner-wide b {
  font-weight: 600;
}

.auth-steps {
  flex-direction: column;
  gap: 16px;
  display: flex;
}

.auth h1 {
  font-family: var(--read);
  letter-spacing: -.015em;
  overflow-wrap: anywhere;
  margin: 6px 0 0;
  font-size: 38px;
  font-weight: 400;
  line-height: 1.06;
}

.auth h1[tabindex="-1"]:focus, .auth-form-col[tabindex="-1"]:focus {
  outline: none;
}

.auth-tagline {
  color: var(--text-muted);
  margin: -6px 0 2px;
  font-size: 15px;
}

.auth-tagline b {
  color: var(--text);
  font-weight: 500;
}

.auth-foot {
  color: var(--text-muted);
  flex-direction: column;
  gap: 6px;
  margin-top: 4px;
  font-size: 12.5px;
  display: flex;
}

.auth-corner {
  color: var(--text-muted);
  font-size: 12px;
  text-decoration: none;
  position: absolute;
  bottom: 22px;
  right: 28px;
}

.auth-corner:hover {
  text-underline-offset: 3px;
  text-decoration: underline;
}

.auth-form-col:has(.consent-notice-column) {
  padding-block: max(80px, calc(var(--consent-room, 0px) + 40px));
}

.auth-form-col:has(.consent-notice-column) .auth-corner {
  display: none;
}

.auth .button:not(.button-link) {
  border-radius: 2px;
  min-height: 40px;
  padding: 8px 16px;
  font-size: 14px;
}

.auth .button:not(.button-quiet):not(.button-link):hover:not(:disabled):not([aria-disabled="true"]) {
  background: var(--accent-strong);
}

.auth .button-quiet:hover:not(:disabled) {
  box-shadow: inset 0 0 0 1px var(--text-decor);
  background: var(--hover-fill);
}

.auth .button:disabled, .auth .button[aria-disabled="true"] {
  cursor: default;
  opacity: .45;
}

.auth .auth-full {
  width: 100%;
}

.auth-link {
  color: var(--accent);
  cursor: pointer;
  font: inherit;
  text-align: left;
  text-underline-offset: 3px;
  background: none;
  border: 0;
  padding: 0;
  font-size: 13px;
  text-decoration: underline;
}

.auth-link-muted {
  color: var(--text-muted);
}

.auth-link-solo {
  align-self: flex-start;
}

.auth a.button {
  text-decoration: none;
}

.auth-link:disabled {
  color: var(--text-decor);
  cursor: default;
  text-decoration: none;
}

.auth .field-control {
  min-height: 42px;
  color: var(--text);
  padding: 9px 12px;
  font-size: 14.5px;
}

.auth .field-control:focus {
  outline: 2px solid var(--accent);
  outline-offset: -1px;
  border-color: #0000;
}

.auth .field-control[readonly] {
  background: var(--surface-board);
  color: var(--text-muted);
}

.auth .field-hint {
  font-size: 12.5px;
}

.auth-opt {
  color: var(--text-muted);
  font-weight: 400;
}

.auth .notice {
  padding: 10px 12px;
  font-size: 13px;
}

.auth .notice strong {
  margin: 0 .25em 0 0;
  display: inline;
}

.notice-warn {
  border-left-color: var(--warn);
  background: var(--warn-soft);
  color: var(--text);
}

.auth-divider {
  color: var(--text-muted);
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 10px;
  font-size: 12px;
  display: grid;
}

.auth-divider:before, .auth-divider:after {
  background: var(--rule);
  content: "";
  height: 1px;
}

.auth-gicon {
  width: 16px;
  height: 16px;
}

.auth-links {
  flex-wrap: wrap;
  align-items: center;
  gap: 18px;
  display: flex;
}

.auth-pair {
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  display: grid;
}

.auth .field-control[aria-invalid="true"] {
  border-color: var(--warn);
}

.auth .field-control[aria-invalid="true"] ~ .field-hint, .auth .auth-chips + .field-hint {
  color: var(--warn);
}

.auth-chips {
  flex-wrap: wrap;
  gap: 6px;
  display: flex;
}

.auth-chip {
  background: var(--surface-panel);
  box-shadow: inset 0 0 0 1px var(--rule);
  color: var(--text);
  cursor: pointer;
  font: inherit;
  border: 0;
  border-radius: 15px;
  padding: 6px 11px;
  font-size: 12.5px;
  line-height: 1.5;
}

.auth-chip:hover {
  box-shadow: inset 0 0 0 1px var(--text-decor);
}

.auth-chip:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.auth-chip[aria-checked="true"] {
  background: var(--text);
  color: var(--on-ink);
  box-shadow: none;
}

.auth-trap {
  width: 1px;
  height: 1px;
  position: absolute;
  left: -10000px;
  overflow: hidden;
}

.auth-code {
  place-self: flex-start start;
  position: relative;
}

.auth-code-cells {
  gap: 8px;
  display: flex;
}

.auth-code-cells span {
  border: 1px solid var(--rule);
  background: var(--surface-panel);
  width: 48px;
  height: 56px;
  color: var(--text);
  font-family: var(--read);
  border-radius: 2px;
  place-items: center;
  font-size: 22px;
  display: grid;
