.qrow {
  background: var(--quote-paper);
  box-shadow: inset 0 0 0 1px var(--quote-rule);
  font-family: var(--read);
  border-radius: 6px;
  margin: 0 0 8px;
  padding: 10px 12px;
  font-size: 15px;
}

.qrow small {
  font-family: var(--ui);
  color: var(--ink-2);
  margin-top: 3px;
  font-size: 11.5px;
  display: block;
}

.lk-list {
  gap: 4px;
  display: grid;
}

.lk-list button {
  all: unset;
  box-sizing: border-box;
  cursor: pointer;
  border-radius: 5px;
  align-items: center;
  gap: 10px;
  min-width: 0;
  padding: 6px 8px;
  font-size: 13px;
  display: flex;
}

.lk-list button:hover {
  background: var(--hover-fill);
}

.lk-list button:focus-visible {
  outline: var(--focus-ring);
}

.lk-list .th {
  background: var(--surface-board);
  border-radius: 4px;
  flex-shrink: 0;
  width: 30px;
  height: 30px;
  display: grid;
  overflow: hidden;
}

.lk-list .th img {
  object-fit: cover;
  width: 100%;
  height: 100%;
}

.lk-list .lk-title {
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
  overflow: hidden;
}

.lk-list small {
  color: var(--ink-2);
  white-space: nowrap;
  margin-left: auto;
  font-size: 11.5px;
}

.rd-hero .ip-title .ip-title-field, .rd-hero .ip-title-static {
  font-family: var(--read);
  letter-spacing: -.01em;
  font-size: 26px;
  font-weight: 400;
  line-height: 1.15;
}

.rd-hero .ip-side {
  grid-template-columns: 120px minmax(0, 1fr);
  align-items: start;
  gap: 18px;
}

.rd-hero .ip-side.is-book {
  grid-template-columns: 110px minmax(0, 1fr);
}

.rd-hero .ip-wide {
  margin: 0 0 14px;
}

.rd-hero .ip-quote {
  padding: 24px 22px 20px;
}

.rd-hero .ip-note {
  padding: 16px 18px;
}

.rd-hero .ip-note .note-body-lg {
  font-family: var(--read);
  color: var(--ink);
  margin: 0;
  padding: 0 28px 0 0;
  font-size: 17px;
  line-height: 1.6;
}

.rd-hero .ip-quote .quote-text {
  font-family: var(--read);
  color: var(--ink);
  font-size: 22px;
  font-style: italic;
  line-height: 1.35;
}

.rd-hero .inline-edit.ip-lead {
  max-width: 64ch;
  font-family: var(--read);
  color: var(--ink);
  margin: 14px 0 0;
  font-size: 16px;
  line-height: 1.55;
}

.pg-bar {
  color: var(--ink-2);
  font-variant-numeric: tabular-nums;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  margin: 0 0 10px;
  font-size: 12.5px;
  display: flex;
}

.pg-bar .grow {
  flex: 1;
}

.pg-bar .seg {
  box-shadow: inset 0 0 0 1px var(--rule);
  border-radius: 4px;
  align-items: center;
  gap: 2px;
  padding: 1px;
  display: inline-flex;
}

.pg-bar input {
  text-align: center;
  width: 34px;
  font: inherit;
  color: var(--ink);
  box-shadow: inset 0 0 0 1px var(--rule);
  background: var(--surface-float);
  border: 0;
  border-radius: 3px;
  padding: 3px 0;
}

.pg-bar .of {
  white-space: nowrap;
  margin: 0 4px;
}

.pg-bar .zv {
  text-align: center;
  min-width: 42px;
}

.pg-bar .icb:disabled {
  cursor: default;
  opacity: .45;
}

.pg-desk {
  --desk-pad-x: 18px;
  background: var(--surface-board);
  padding: 18px var(--desk-pad-x);
  border-radius: 8px;
  min-height: 220px;
  overflow: auto;
}

.reader .pdf-fit {
  width: 100%;
}

.pg-strip {
  gap: 3px;
  margin: 12px 0 0;
  display: flex;
}

.pg-strip button {
  all: unset;
  cursor: pointer;
  background: var(--rule);
  border-radius: 2px;
  flex: 1;
  height: 16px;
  position: relative;
}

.pg-strip button:hover {
  background: var(--ink-3);
}

.pg-strip button[aria-current="true"] {
  background: var(--ink);
}

.pg-strip button.has:after {
  content: "";
  background: var(--status-2);
  border-radius: 50%;
  width: 5px;
  height: 5px;
  margin-left: -2.5px;
  position: absolute;
  top: -6px;
  left: 50%;
}

.pg-strip button:focus-visible {
  outline: var(--focus-ring);
}

.reader .qv-stage {
  gap: 10px;
}

.reader .qv-media {
  box-shadow: none;
}

.rd-photo-details .qv-cap {
  font-family: var(--read);
  margin: 10px 0 4px;
  font-size: 15px;
}

.rd-photo-details .meta {
  color: var(--ink-2);
  margin: 0 0 12px;
  font-size: 12.5px;
}

.reader .player {
  width: 100%;
}

.reader .player .pic {
  box-shadow: none;
}

.rd-notes {
  border-top: 1px solid var(--rule);
  background: var(--surface-float);
  min-width: 0;
  padding: 8px 12px 12px;
}

.rd-ntoggle {
  all: unset;
  cursor: pointer;
  letter-spacing: .07em;
  text-transform: uppercase;
  color: var(--ink-2);
  align-items: center;
  gap: 6px;
  padding: 4px 2px 6px;
  font-size: 10.5px;
  font-weight: 600;
  display: flex;
}

.rd-ntoggle i {
  transition: transform var(--dur-standard) ease;
  font-style: normal;
  display: inline-block;
}

.rd-ntoggle[aria-expanded="true"] i {
  transform: rotate(180deg);
}

.rd-ntoggle:focus-visible {
  outline: var(--focus-ring);
}

.rd-nlist {
  gap: 6px;
  max-height: 112px;
  margin: 0 0 8px;
  padding: 0;
  list-style: none;
  display: grid;
  overflow: auto;
}

.rd-nlist .nt {
  background: var(--note-paper);
  box-shadow: inset 2.5px 0 0 var(--status-2), inset 0 0 0 1px var(--rule);
  overflow-wrap: anywhere;
  border-radius: 6px;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: start;
  gap: 8px;
  padding: 7px 10px;
  font-size: 13px;
  display: grid;
}

.rd-nlist .nt.q {
  background: var(--quote-paper);
  box-shadow: inset 2.5px 0 0 var(--accent), inset 0 0 0 1px var(--quote-rule);
  font-family: var(--read);
  font-size: 14px;
}

.rd-nlist .nt .loc {
  font-family: var(--ui);
  color: var(--accent);
  background: var(--accent-soft);
  white-space: nowrap;
  cursor: pointer;
  border: 0;
  border-radius: 9px;
  padding: 1px 7px;
  font-size: 11px;
}

.rd-nlist .nt .loc.is-whole {
  cursor: default;
  color: var(--ink-2);
  box-shadow: inset 0 0 0 1px var(--rule);
  background: none;
}

.rd-nlist .nt .loc:focus-visible {
  outline: var(--focus-ring);
}

.rd-comp {
  background: var(--surface-panel);
  box-shadow: inset 0 0 0 1px var(--rule);
  border-radius: 8px;
  gap: 6px;
  padding: 8px 10px;
  display: grid;
}

.rd-comp:focus-within {
  box-shadow: inset 0 0 0 1px var(--ink-3);
}

.rd-comp textarea {
  all: unset;
  box-sizing: border-box;
  width: 100%;
  min-height: 40px;
  max-height: 140px;
  font-family: var(--read);
  color: var(--ink);
  white-space: pre-wrap;
  field-sizing: content;
  font-size: 14.5px;
  line-height: 1.45;
  overflow: auto;
}

.rd-comp textarea::placeholder {
  color: var(--text-muted);
}

.rd-tools {
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  min-width: 0;
  display: flex;
}

.rd-tools .grow {
  flex: 1;
}

.rd-hint {
  color: var(--ink-2);
  font-size: 11px;
}

@media (hover: none), (max-width: 1099.98px) {
  .rd-hint {
    display: none;
  }
}

.pill-btn.top {
  color: var(--ink);
  background: var(--surface-float);
  box-shadow: inset 0 0 0 1px var(--rule);
  max-width: 220px;
}

.pill-btn.top .pill-name {
  text-overflow: ellipsis;
  overflow: hidden;
}

.pill-btn.top .x {
  color: var(--ink-2);
  font-size: 13px;
  line-height: 1;
}

.pill-btn.top.none {
  color: var(--ink-2);
  background: none;
}

.pill-btn.loc.is-static {
  cursor: default;
}

.rd-send {
  all: unset;
  box-sizing: border-box;
  cursor: pointer;
  background: var(--ink);
  width: 28px;
  height: 28px;
  color: var(--on-ink);
  transition: transform var(--dur-instant) ease, opacity var(--dur-quick) ease;
  border-radius: 50%;
  place-items: center;
  display: grid;
}

.rd-send:disabled {
  cursor: default;
  opacity: .35;
}

.rd-send:active:not(:disabled) {
  transform: scale(var(--press-scale));
}

.rd-send:focus-visible {
  outline: var(--focus-ring);
  outline-offset: 2px;
}

@media (max-width: 1099.98px) {
  .rdwrap {
    z-index: 60;
    width: auto;
    height: 88vh;
    position: fixed;
    inset: auto 0 0;
  }

  .reader {
    border-radius: 14px 14px 0 0;
    grid-template-rows: auto minmax(0, 1fr);
    grid-template-columns: minmax(0, 1fr);
    inset: 0;
  }

  .rd-film {
    border-right: 0;
    border-bottom: 1px solid var(--rule);
    grid-auto-columns: 44px;
    grid-auto-flow: column;
    justify-content: start;
    padding: 8px 12px;
    overflow: auto hidden;
  }

  .rd-film .fl, .rd-head .wideb, .rd-full .l {
    display: none;
  }

  .rd-full .s {
    display: inline;
  }

  .rd-back {
    max-width: 38%;
  }

  .rd-scroll {
    padding: 14px 16px 18px;
  }

  .pg-desk {
    --desk-pad-x: 10px;
    padding: 10px;
  }

  .cpwrap.is-reading {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .rdwrap, .gbtns, .gzoom-controls, .cpwrap.is-reading .cp, .graph.is-reading .graph-lib, .graph.is-reading .graph-svg [data-lane], .rd-thumb, .rd-ntoggle i, .rd-send {
    transition: none;
  }

  .rd-scroll[data-swap] {
    animation: none;
  }

  .rd-film button:hover .rd-thumb {
    transform: none;
  }
}

.graph-ghost-specimen h1 {
  font-family: var(--read);
  margin: 0 0 8px;
  font-size: 24px;
  font-weight: 400;
}

.graph-ghost-specimen p {
  max-width: 60ch;
  color: var(--ink-2);
  font-size: 13px;
}

.graph-ghost-specimen svg {
  width: min(520px, 100%);
  height: auto;
  display: block;
}

.gp-wrap {
  z-index: 12;
  pointer-events: none;
  position: absolute;
}

.gp-wrap[data-mode="panel"] {
  top: 52px;
  right: calc(var(--t-panel) + 12px);
  flex-direction: column;
  display: flex;
  bottom: 44px;
}

.gp-wrap[data-mode="panel"][data-place="over"] {
  right: 12px;
}

.gp-wrap[data-mode="panel"] .gp-panel {
  pointer-events: auto;
  box-sizing: border-box;
  background: var(--surface-float);
  min-height: 0;
  max-height: 100%;
  box-shadow: var(--shadow-float), inset 0 0 0 1px var(--rule);
  transform-origin: 100% 0;
  animation: gp-pop calc(var(--dur-move) + var(--dur-quick)) var(--ease-spring);
  border-radius: 12px;
  flex-direction: column;
  display: flex;
  position: relative;
}

.gp-panel:focus {
  outline: none;
}

.gp-panel:focus-visible {
  outline: var(--focus-ring);
  outline-offset: 2px;
}

@keyframes gp-pop {
  from {
    opacity: 0;
    transform: translateX(14px)scale(.97);
  }

  to {
    opacity: 1;
    transform: none;
  }
}

.graph.is-player-over .cpwrap .cp {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transform: translateX(28px)scale(.98);
}

.gp-surface {
  min-height: 0;
  animation: gp-fade var(--dur-standard) ease;
  flex-direction: column;
  flex: auto;
  display: flex;
}

@keyframes gp-fade {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

.gp-head {
  flex: none;
  padding: 12px 10px 10px 16px;
  display: block;
}

.gp-toprow {
  align-items: center;
  gap: 4px;
  display: flex;
}

.gp-kicker {
  flex: 1;
  min-width: 0;
  display: block;
}

.gp-kicker b {
  color: var(--ink-2);
  font-weight: 400;
}

.gp-back {
  all: unset;
  cursor: pointer;
  color: var(--ink-2);
  border-radius: 3px;
}

.gp-back:hover {
  color: var(--ink);
}

.gp-back:focus-visible {
  outline: var(--focus-ring);
  outline-offset: 2px;
}

.gp-full {
  color: var(--accent);
  white-space: nowrap;
  border-radius: 4px;
  padding: 3px 8px;
  font-size: 12.5px;
  font-weight: 500;
  text-decoration: none;
}

.gp-full:hover {
  background: var(--accent-soft);
}

.gp-full:focus-visible {
  outline: var(--focus-ring);
  outline-offset: 2px;
}

.gp-body {
  flex: none;
  padding: 12px 12px 10px;
}

.gp-surface .xp-screen {
  gap: 8px;
}

.gp-surface .xp-screen:not([data-fullscreen="true"]) .xp-screen-fit {
  aspect-ratio: 16 / 9;
  flex: none;
  width: 100%;
}

.gp-surface .xp-ctrl {
  flex-wrap: nowrap;
  gap: 2px;
}

.gp-surface .xp-ctrl .xp-ib {
  width: 30px;
  height: 30px;
}

.gp-surface .xp-ctrl .xp-ib svg {
  width: 16px;
  height: 16px;
}

.gp-surface .xp-ctrl .xp-ib.xp-ib-play {
  width: 32px;
  height: 32px;
  margin-right: 4px;
}

.gp-surface .xp-ctrl .xp-ib.xp-ib-play svg {
  width: 14px;
  height: 14px;
}

.gp-surface .xp-ctrl .xp-scrub {
  min-width: 120px;
  margin-inline: 6px 10px;
}

.gp-surface .xp-tm {
  min-width: 74px;
}

.gp-surface .xp-spd {
  margin: 0 4px 0 2px;
  padding: 3px 7px;
}

.gp-meta {
  margin-top: 4px;
  padding: 0 2px;
}

.gp-meta .xp-meta-line {
  flex-wrap: nowrap;
  font-size: 12px;
}

.gp-ttoggle {
  all: unset;
  cursor: pointer;
  color: var(--ink-2);
  white-space: nowrap;
  border-radius: 4px;
  align-items: center;
  gap: 5px;
  margin-left: auto;
  padding: 3px 6px;
  font-size: 12px;
  display: inline-flex;
}

.gp-ttoggle:hover {
  background: var(--hover-fill);
  color: var(--ink);
}

.gp-ttoggle:focus-visible {
  outline: var(--focus-ring);
  outline-offset: 2px;
}

.gp-ttoggle i {
  transition: transform var(--dur-standard) ease;
  font-style: normal;
  display: inline-block;
}

.gp-ttoggle[aria-expanded="true"] {
  color: var(--accent);
}

.gp-ttoggle[aria-expanded="true"] i {
  transform: rotate(180deg);
}

.gp-drawer {
  border-top: 1px solid var(--rule);
  flex: 0 230px;
  height: 230px;
  min-height: 0;
}

.gp-drawer[hidden] {
  display: none;
}

.gp-drawer .xp-tx {
  width: 100%;
  min-width: 0;
  max-width: none;
  height: 100%;
  min-height: 0;
}

.gp-drawer .xp-tx-in {
  box-shadow: none;
  background: none;
  border-radius: 0 0 12px 12px;
}

.gp-loading .xp-box {
  box-shadow: inset 0 0 0 1px var(--line);
}

.gp-failed {
  color: var(--ink-2);
  gap: 10px;
  padding: 18px 4px 8px;
  font-size: 13px;
  display: grid;
}

.gp-failed p {
  margin: 0;
}

.gp-failed-acts {
  flex-wrap: wrap;
  gap: 8px;
  display: flex;
}

.gp-wrap[data-mode="dock"] {
  bottom: 46px;
  left: calc(var(--graph-gutter) + (100% - var(--graph-gutter) - var(--t-panel) - 12px) / 2);
  width: 360px;
  transform: translateX(-50%);
}

.graph.is-folded .gp-wrap[data-mode="dock"] {
  left: calc(var(--graph-gutter) + (100% - var(--graph-gutter)) / 2);
}

.gp-dock {
  pointer-events: auto;
  box-sizing: border-box;
  background: var(--surface-float);
  box-shadow: var(--shadow-float), inset 0 0 0 1px var(--rule);
  animation: gp-dock-in var(--dur-move) var(--ease-entrance);
  border-radius: 10px;
  align-items: center;
  gap: 10px;
  padding: 8px 8px 10px;
  display: flex;
  position: relative;
  overflow: hidden;
}

.gp-dock:focus {
  outline: none;
}

@keyframes gp-dock-in {
  from {
    opacity: 0;
    transform: translateY(10px);
  }

  to {
    opacity: 1;
    transform: none;
  }
}

.gp-dock-poster {
  aspect-ratio: 16 / 9;
  width: 64px;
  box-shadow: inset 0 0 0 1px var(--line);
  background: var(--panel);
  border-radius: 2px;
  flex: none;
  display: block;
  overflow: hidden;
}

.gp-dock-poster * {
  max-width: none;
}

.gp-dock-text {
  flex: 1;
  min-width: 0;
  line-height: 1.25;
}

.gp-dock-k {
  color: var(--accent);
  letter-spacing: .07em;
  text-transform: uppercase;
  align-items: center;
  gap: 6px;
  font-size: 10.5px;
  display: flex;
}

.gp-dock-text b {
  font-family: var(--read);
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 15px;
  font-weight: 400;
  display: block;
  overflow: hidden;
}

.gp-dock-text small {
  color: var(--ink-2);
  font-variant-numeric: tabular-nums;
  font-size: 11.5px;
}

.gp-dock .xp-ib.xp-ib-play {
  width: 32px;
  height: 32px;
  margin: 0;
}

.gp-dock-prog {
  background: var(--line);
  height: 2px;
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
}

.gp-dock-prog i {
  background: var(--accent);
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
}

.gp-level {
  align-items: flex-end;
  gap: 1.5px;
  height: 9px;
  display: inline-flex;
}

.gp-level i {
  transform-origin: bottom;
  background: currentColor;
  width: 2px;
  height: 100%;
  animation: .9s ease-in-out infinite gp-level;
}

.gp-level i:nth-child(2) {
  animation-delay: -.3s;
}

.gp-level i:nth-child(3) {
  animation-delay: -.6s;
}

@keyframes gp-level {
  0%, 100% {
    transform: scaleY(.35);
  }

  50% {
    transform: scaleY(1);
  }
}

.cp-xcard-playing {
  background: var(--accent-soft);
  color: var(--accent);
  box-shadow: none;
  align-items: center;
  gap: 6px;
  display: inline-flex;
}

.graph-xlane.is-playing .lane-card {
  stroke: var(--accent);
  stroke-width: 1.5px;
}

.graph-xlane.is-playing .lane-kind {
  fill: var(--accent);
}

.gp-scrim {
  z-index: 60;
  background: var(--scrim-dialog);
  animation: dialog-scrim-in var(--dur-quick) var(--ease-standard);
  position: fixed;
  inset: 0;
}

@media (max-width: 1099.98px) {
  .gp-wrap[data-mode="panel"] {
    z-index: 61;
    width: auto;
    position: fixed;
    inset: auto 0 0;
  }

  .gp-wrap[data-mode="panel"] .gp-panel {
    max-height: 88dvh;
    padding-bottom: env(safe-area-inset-bottom);
    transform-origin: bottom;
    animation: gp-sheet-in var(--dur-move) var(--ease-entrance);
    border-radius: 14px 14px 0 0;
    overflow: auto;
  }

  .gp-wrap[data-mode="panel"] .gp-panel:before {
    content: "";
    background: var(--line);
    border-radius: 2px;
    flex: none;
    width: 36px;
    height: 4px;
    margin: 8px auto 0;
    display: block;
  }

  .gp-head {
    padding-top: 6px;
  }

  .gp-kicker-subject {
    display: none;
  }

  .gp-surface .xp-ctrl {
    flex-wrap: wrap;
    row-gap: 4px;
  }

  .gp-surface .xp-ctrl .xp-scrub {
    flex-basis: calc(100% - 96px);
    order: -2;
    margin-inline: 4px 8px;
  }

  .gp-surface .xp-ctrl .xp-tm {
    order: -1;
    min-width: 0;
  }

  .gp-surface .xp-ctrl .xp-ib.xp-ib-play {
    margin-right: auto;
  }

  .gp-wrap[data-mode="dock"], .graph.is-folded .gp-wrap[data-mode="dock"] {
    z-index: 59;
    width: auto;
    position: fixed;
