  width: 100%;
  height: 100%;
  display: block;
}

.player .play {
  background: var(--surface-float);
  opacity: .9;
  width: 64px;
  height: 64px;
  box-shadow: var(--shadow-pic);
  pointer-events: none;
  border-radius: 50%;
  place-items: center;
  margin: -32px 0 0 -32px;
  display: grid;
  position: absolute;
  top: 50%;
  left: 50%;
}

.player .play:before {
  content: "";
  border-left: 13px solid var(--ink);
  border-top: 8px solid #0000;
  border-bottom: 8px solid #0000;
  margin-left: 4px;
}

