.cv-err {
  color: var(--warn);
  margin: 8px 0 0;
  font-size: 12.5px;
}

.cv-fieldset {
  border: 0;
  margin: 0 0 14px;
  padding: 0;
}

.cv-fieldset legend, .cv-fl {
  margin-bottom: 6px;
  padding: 0;
  font-size: 13px;
  font-weight: 500;
  display: block;
}

.cv-ropt {
  cursor: pointer;
  border-radius: 2px;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  display: flex;
}

.cv-ropt:hover {
  background: var(--hover-fill);
}

.cv-ropt[data-on="true"] {
  box-shadow: inset 0 0 0 1px var(--accent);
}

.cv-ropt input, .cv-chk input {
  accent-color: var(--accent);
  margin: 0;
}

.cv-chk {
  color: var(--ink-2);
  align-items: center;
  gap: 8px;
  margin-top: 12px;
  display: flex;
}

.cv-chk b {
  color: var(--ink);
  font-weight: 500;
}

.cv-stage-pending {
  aspect-ratio: 16 / 9;
  background: var(--panel);
  box-shadow: inset 0 0 0 1px var(--line), 0 1px 2px var(--shade);
}

@supports (color: color-mix(in lab, red, red)) {
  .cv-stage-pending {
    box-shadow: inset 0 0 0 1px var(--line), 0 1px 2px color-mix(in srgb, var(--shade) 16%, transparent);
  }
}

.cv-stage-pending {
  cursor: default;
}

.cv-stage-pending .cv-upnext {
  background: none;
  animation: none;
}

.cv-upnext-card {
  gap: 10px;
  width: min(100%, max(330px, 50cqw));
}

.cv-upnext-card h2 {
  padding-right: 26px;
  font-size: max(19px, 2.3cqw);
}

.cv-up-w {
  color: var(--ink-2);
  margin: 0;
  font-size: 12px;
}

.cv-up-ab {
  color: var(--ink-2);
  font-family: var(--read);
  margin: 0;
  font-size: max(14.5px, 1.35cqw);
  line-height: 1.45;
}

.cv-up-nm {
  background: var(--paper);
  box-shadow: inset 0 0 0 1px var(--line);
  color: var(--ink-2);
  align-items: flex-start;
  gap: 8px;
  margin: 0;
  padding: 8px 10px;
  font-size: 12.5px;
  line-height: 1.45;
  display: flex;
}

.cv-up-nm svg {
  width: 15px;
  height: 15px;
  color: var(--text-decor);
  flex: none;
  margin-top: 1px;
}

.cv-up-acts {
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-top: 2px;
  display: flex;
}

.cv-up-acts .button svg {
  width: 13px;
  height: 13px;
}

.cv-below {
  background: var(--panel);
  box-shadow: inset 0 0 0 1px var(--line);
  margin-top: 18px;
}

.cv-tabs {
  border-bottom: 1px solid var(--line);
  gap: 2px;
  padding: 8px 10px 0;
  display: flex;
}

.cv-tab {
  color: var(--ink-2);
  font: inherit;
  cursor: pointer;
  background: none;
  border: 0;
  border-bottom: 2px solid #0000;
  margin-bottom: -1px;
  padding: 6px 10px 8px;
  font-size: 13px;
}

.cv-tab[aria-selected="true"] {
  border-bottom-color: var(--accent);
  color: var(--ink);
  font-weight: 500;
}

.cv-tab:focus-visible {
  outline: var(--focus-ring);
  outline-offset: -2px;
}

.cv-tab-narrow {
  display: none;
}

.cv-tx-body {
  max-height: 460px;
}

.cv-tbody {
  grid-template-columns: minmax(0, .9fr) minmax(0, 1.1fr);
  display: grid;
}

.cv-tsec {
  padding: 14px 18px 18px;
}

.cv-tsec + .cv-tsec {
  border-left: 1px solid var(--line);
}

.cv-tsec h2 {
  color: var(--ink-2);
  letter-spacing: .04em;
  text-transform: uppercase;
  margin: 0 0 10px;
  font-size: 11.5px;
  font-weight: 600;
}

.cv-place {
  font-family: var(--read);
  margin: 0 0 4px;
  font-size: 17px;
  line-height: 1.3;
}

.cv-place-sub {
  color: var(--ink-2);
  margin: 0;
  font-size: 12.5px;
  line-height: 1.45;
}

.cv-place-gap {
  margin-top: 10px;
}

.cv-strip {
  gap: 2px;
  height: 10px;
  margin: 14px 0 4px;
  display: flex;
}

.cv-strip i {
  background: var(--line);
  border-radius: 1px;
  height: 100%;
  display: block;
}

.cv-strip i.on {
  background: var(--accent);
}

.cv-strip i.seen {
  background: var(--status-1);
}

.cv-strip-l {
  color: var(--ink-2);
  font-variant-numeric: tabular-nums;
  justify-content: space-between;
  font-size: 11px;
  display: flex;
}

.cv-legend {
  color: var(--ink-2);
  flex-wrap: wrap;
  gap: 4px 14px;
  margin: 10px 0 0;
  font-size: 11.5px;
  display: flex;
}

.cv-legend span {
  align-items: center;
  gap: 5px;
  display: inline-flex;
}

.cv-legend i {
  background: var(--line);
  border-radius: 1px;
  width: 10px;
  height: 6px;
}

.cv-legend i.on {
  background: var(--accent);
}

.cv-legend i.seen {
  background: var(--status-1);
}

.cv-links {
  flex-wrap: wrap;
  gap: 6px 16px;
  margin-top: 12px;
  font-size: 12.5px;
  display: flex;
}

.cv-links a {
  color: var(--accent);
  text-decoration: none;
}

.cv-links a:hover {
  text-decoration: underline;
}

.cv-path {
  color: var(--ink-2);
  flex-wrap: wrap;
  align-items: center;
  gap: 5px;
  margin: 0 0 8px;
  font-size: 12.5px;
  display: flex;
}

.cv-path i {
  font-style: normal;
}

.cv-path b {
  color: var(--ink);
  font-weight: 600;
}

.cv-sm {
  border: 1px solid var(--line);
  color: var(--ink-2);
  border-radius: 2px;
  align-items: center;
  gap: 6px;
  padding: 2px 8px;
  font-size: 11.5px;
  display: inline-flex;
}

.cv-sm i {
  border: 1px solid var(--status-2);
  border-radius: 50%;
  width: 9px;
  height: 9px;
}

.cv-sm i.s1 {
  border-color: var(--status-1);
  background: var(--status-1);
}

.cv-sm i.s2 {
  border-color: var(--status-2);
  background: var(--status-2);
}

.cv-cites {
  gap: 2px;
  margin: 0;
  padding: 0;
  list-style: none;
  display: grid;
}

.cv-cite {
  all: unset;
  box-sizing: border-box;
  cursor: pointer;
  border-radius: 2px;
  grid-template-columns: 54px minmax(0, 1fr);
  gap: 10px;
  width: 100%;
  padding: 7px 8px;
  display: grid;
}

.cv-cite:hover:not(:disabled) {
  background: var(--hover-fill);
}

.cv-cite:focus-visible {
  outline: var(--focus-ring);
  outline-offset: -2px;
}

.cv-cite:disabled {
  cursor: default;
}

.cv-loc {
  border: 1px solid var(--line);
  color: var(--ink-2);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  border-radius: 2px;
  place-self: start;
  margin-top: 2px;
  padding: 1px 6px;
  font-size: 11px;
}

.cv-cite q {
  color: var(--ink);
  font-family: var(--read);
  quotes: "“" "”";
  font-size: 15px;
  line-height: 1.4;
  display: block;
}

.cv-cite small {
  color: var(--ink-2);
  margin-top: 2px;
  font-size: 11.5px;
  display: block;
}

.cv-cite-wait q {
  color: var(--ink-2);
  font-style: italic;
}

.cv-cite-sum {
  color: var(--ink-2);
  margin: 10px 0 0;
  font-size: 12px;
}

.cv-rd {
  grid-template-columns: minmax(0, 66ch) minmax(200px, 1fr);
  gap: 0 40px;
  padding: 20px 24px 28px;
  display: grid;
}

.cv-reading {
  min-width: 0;
  color: var(--ink);
  font-family: var(--read);
  font-size: 18px;
  line-height: 1.56;
}

.cv-rmeta {
  color: var(--ink-2);
  font-family: var(--ui);
  margin: 0 0 10px;
  font-size: 12px;
  line-height: 1.4;
}

.cv-reading h3 {
  font-family: var(--read);
  letter-spacing: -.005em;
  margin: 0 0 12px;
  font-size: 26px;
  font-weight: 400;
  line-height: 1.15;
}

.cv-reading h4 {
  font-family: var(--ui);
  margin: 22px 0 8px;
  font-size: 13px;
  font-weight: 600;
}

.cv-reading p {
  margin: 0 0 14px;
}

.cv-reading ul, .cv-reading ol {
  margin: 0 0 14px;
  padding-left: 20px;
}

.cv-reading li {
  margin: 4px 0;
}

.cv-reading blockquote {
  border-left: 2px solid var(--accent);
  margin: 16px 0;
  padding: 2px 0 2px 16px;
  font-style: italic;
}

.cv-reading a {
  color: var(--accent);
}

.cv-reading cite {
  border: 1px solid var(--line);
  color: var(--ink-2);
  font-family: var(--ui);
  vertical-align: 1px;
  cursor: pointer;
  border-radius: 2px;
  margin-left: 4px;
  padding: 0 5px;
  font-size: 11px;
  font-style: normal;
  line-height: 1.5;
  display: inline-block;
}

.cv-reading-note {
  color: var(--ink-2);
  font-family: var(--ui);
}

.cv-rd-side {
  background: var(--paper);
  box-shadow: inset 0 0 0 1px var(--line);
  color: var(--ink-2);
  font-family: var(--ui);
  align-self: start;
  padding: 14px 16px;
  font-size: 12.5px;
  line-height: 1.45;
}

.cv-rd-side h4 {
  color: var(--ink);
  letter-spacing: .04em;
  text-transform: uppercase;
  margin: 0 0 8px;
  font-size: 11.5px;
  font-weight: 600;
}

.cv-rd-side dl {
  gap: 8px;
  margin: 0;
  display: grid;
}

.cv-rd-side dt {
  color: var(--ink);
  font-weight: 600;
}

.cv-rd-side dd {
  margin: 0;
}

.cv-skel {
  gap: 10px;
  padding: 4px 0;
  display: grid;
}

.cv-skel i {
  background: var(--surface-board);
  border-radius: 2px;
  height: 12px;
  display: block;
}

.cv-skel .cv-skel-gap {
  background: none;
  width: 0;
  height: 6px;
}

.cv-scrim {
  z-index: 43;
  background: var(--scrim-dialog);
  position: fixed;
  inset: 0;
}

.cv-sheet {
  z-index: 44;
  height: var(--cv-sheet-h, 67dvh);
  max-height: calc(100dvh - var(--m-bar));
  padding-bottom: env(safe-area-inset-bottom, 0px);
  border-radius: var(--m-sheet-radius) var(--m-sheet-radius) 0 0;
  background: var(--panel);
  box-shadow: var(--shadow-float);
  transition: height var(--dur-standard) var(--ease-entrance);
  animation: dialog-sheet-in var(--dur-standard) var(--ease-entrance);
  flex-direction: column;
  display: flex;
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  overflow: hidden;
}

.cv-sheet[data-dragging] {
  transition: none;
  height: max(0px, var(--drag-h)) !important;
}

.cv-sheet .cp-grip {
  z-index: 1;
  height: var(--m-hit);
  position: absolute;
  top: 0;
  left: 56px;
  right: 56px;
}

.cv-sheet-top {
  flex: none;
  justify-content: space-between;
  align-items: center;
  padding: 14px 8px 0 18px;
  display: flex;
}

body:has(.cv-sheet) .tab-bar {
  display: none;
}

.cv-sheet-top b {
  font-size: 13px;
  font-weight: 600;
}

.cv-sheet .cv-sheet-x {
  width: 44px;
  height: 44px;
}

.cv-sheet .cv-ol {
  background: var(--panel);
  border-right: 0;
  flex: 1 1 0;
}

@media (max-width: 1023px) {
  .cv-side {
    display: none;
  }

  .cv-page .xp-player {
    flex-direction: column;
    align-items: stretch;
  }

  .cv-page .xp-pcol {
    flex: none;
  }

  .cv-page .xp-ctrl [aria-label="Transcript"] {
    display: none;
  }

  .cv-narrow-side {
    flex-wrap: wrap;
    align-items: center;
    gap: 8px 12px;
    margin-top: 4px;
    display: flex;
  }

  .cv-narrow-side .cv-sm-row {
    flex: 100%;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: center;
    gap: 10px;
    margin: 0;
  }

  .cv-narrow-side .cv-fb-row {
    flex: 100%;
    margin-top: 0;
  }

  .cv-tab-narrow {
    display: inline-block;
  }

  .cv-rd {
    grid-template-columns: 1fr;
    gap: 16px;
  }
}

@media (max-width: 1099.98px) {
  .cv {
    display: block;
  }

  .cv > .cv-ol {
    display: none;
  }

  .cv-main {
    padding: 14px 28px 40px;
  }

  .cv-tbody {
    grid-template-columns: 1fr;
  }

  .cv-tsec + .cv-tsec {
    border-top: 1px solid var(--line);
    border-left: 0;
  }

  .cv-pn {
    display: none;
  }

  .cv-ep {
    gap: 8px;
    padding: 4px;
  }

  .cv-ep-l {
    min-height: var(--m-hit);
    padding: 4px 8px;
  }

  .cv-ep-c {
    display: none;
  }

  .cv-ep-parts {
    all: unset;
    box-sizing: border-box;
    min-height: var(--m-hit);
    background: var(--paper);
    box-shadow: inset 0 0 0 1px var(--line);
    cursor: pointer;
    border-radius: 2px;
    justify-content: center;
    align-items: center;
    gap: 8px;
    padding: 0 16px;
    font-size: 13.5px;
    font-weight: 500;
    display: flex;
  }

  .cv-ep-parts:focus-visible {
    outline: var(--focus-ring);
  }

  .cv-ep-parts svg {
    width: 16px;
    height: 16px;
    color: var(--ink-2);
  }

  .cv-ep-parts small {
    color: var(--ink-2);
    font-variant-numeric: tabular-nums;
    font-weight: 400;
  }
}

@media (min-width: 700px) and (max-width: 1099.98px) {
  .cv-sheet {
    border-radius: 0 var(--m-sheet-radius) var(--m-sheet-radius) 0;
    width: min(360px, 86vw);
    height: auto;
    max-height: none;
    animation: cv-drawer-in var(--dur-standard) var(--ease-entrance);
    transition: none;
    top: 0;
    right: auto;
  }

  .cv-sheet .cp-grip {
    display: none;
  }

  .cv-sheet-top {
    padding-top: 10px;
  }

  .cv-sheet .cv-pt {
    align-content: center;
    min-height: 48px;
  }
}

@keyframes cv-drawer-in {
  from {
    transform: translateX(-100%);
  }

  to {
    transform: none;
  }
}

@media (max-width: 1023.98px) and (min-height: 560px) {
  .cv {
    --cv-top: 0px;
  }

  .cv-main {
    padding-top: 0;
  }

  .cv-main-in {
    padding-top: 14px;
  }

  .cv-page {
    gap: 8px;
    container-type: inline-size;
  }

  .cv-page > .xp-player, .cv-page .xp-pcol {
    display: contents;
  }

  .cv-page .xp-pcol {
    container-type: normal;
  }

  .cv-page .xp-screen:not([data-fullscreen]) {
    top: var(--cv-top);
    z-index: 6;
    background: var(--paper);
    box-shadow: 0 10px 16px -14px var(--shade);
    margin-top: -8px;
    padding-top: 8px;
    padding-bottom: 6px;
    position: sticky;
  }

  @supports (color: color-mix(in lab, red, red)) {
    .cv-page .xp-screen:not([data-fullscreen]) {
      box-shadow: 0 10px 16px -14px color-mix(in srgb, var(--shade) 40%, transparent);
    }
  }

  .cv-tabs {
    top: calc(var(--cv-top) + var(--cv-screen-h, 0px));
    z-index: 5;
    background: var(--panel);
    position: sticky;
  }
}

@media (min-width: 1024px) and (max-width: 1099.98px) and (min-height: 900px) {
  .cv-page > .xp-player {
    z-index: 6;
    background: var(--paper);
    box-shadow: 0 10px 16px -14px var(--shade);
    margin-top: -8px;
    padding-top: 8px;
    padding-bottom: 8px;
    position: sticky;
    top: 0;
  }

  @supports (color: color-mix(in lab, red, red)) {
    .cv-page > .xp-player {
      box-shadow: 0 10px 16px -14px color-mix(in srgb, var(--shade) 40%, transparent);
    }
  }
}

@media (max-width: 699.98px) {
  .cv {
    height: auto;
  }

  .cv-main {
    height: auto;
    padding: 0 var(--m-gutter) 12px;
    overflow: visible;
  }

  .cv-main-in {
    padding-top: 10px;
  }

  .cv-crumb-mid {
    display: none;
  }

  .cv-page .xp-screen-fit {
    height: 56.25cqw;
  }

  .cv-page .xp-ctrl, .cv-page .cv-meta, .cv-page .cv-ep, .cv-page .cv-narrow-side {
    max-width: none;
  }

  .cv-rd {
    padding: 14px 14px 20px;
  }

  .cv-reading {
    font-size: 16px;
    line-height: 1.55;
  }

  .cv-reading h3 {
    font-size: 21px;
  }

  .cv-page .xp-ctrl [aria-label="Back 10 seconds"], .cv-page .xp-ctrl [aria-label="Forward 10 seconds"] {
    display: none;
  }

  .cv-page .xp-ctrl .xp-ib {
    width: var(--m-hit);
    height: var(--m-hit);
  }

  .cv-page .xp-ctrl .xp-spd, .cv-narrow-side .cv-tl {
    min-height: var(--m-hit);
  }

  .cv-tabs {
    scrollbar-width: none;
    overflow-x: auto;
  }

  .cv-tabs::-webkit-scrollbar {
    display: none;
  }

  .cv-tabs .cv-tab {
    min-height: var(--m-hit);
    flex: none;
  }

  .cv-tsec {
    padding: 12px 14px 16px;
  }

  .cv-ep {
    grid-template-columns: var(--m-hit) minmax(0, 1fr) var(--m-hit);
    gap: 6px;
  }

  .cv-ep-l {
    width: var(--m-hit);
    height: var(--m-hit);
    justify-content: center;
    padding: 0;
  }

  .cv-ep-lb {
    display: none;
  }

  .cv-sheet .cv-grp-h {
    min-height: var(--m-hit);
  }

  .cv-sheet .cv-pt {
    align-content: center;
    min-height: 52px;
  }

  .cv-pop {
    width: min(360px, 100vw - 16px);
  }

  .cv-rate button {
    height: var(--m-hit);
    flex: 1;
  }

  .cv-pop .cv-acts {
    flex-direction: column-reverse;
    align-items: stretch;
  }

  .cv-pop .cv-acts .button {
    width: 100%;
    min-height: var(--m-hit);
    justify-content: center;
  }

  .cv-upnext-card {
    gap: 7px;
    padding: 10px 12px;
  }

  .cv-up-ab, .cv-up-w {
    display: none;
  }

  .cv-upnext-card h2 {
    padding-right: 36px;
    font-size: 16px;
    display: block;
  }

  .cv-up-nm {
    padding: 6px 8px;
    font-size: 12px;
  }

  .cv-up-acts .button {
    min-height: var(--m-hit);
    padding: 6px 14px;
  }
}

@media (pointer: coarse) {
  .cv-tab, .cv-tl, .cv-grp-h, .cv-cite, .cv-pn .button, .cv-up-acts .button {
    min-height: var(--m-hit);
  }

  .cv-pt {
    align-content: center;
    min-height: 48px;
  }

  .cv-rate button {
    height: var(--m-hit);
  }

  .cv-ropt {
    min-height: 48px;
  }

  .cv-crumb a {
    margin: -13px 0;
    padding: 13px 0;
    display: inline-block;
  }

  .cv-lnk {
    margin: -13px 0;
    padding: 13px 0;
  }

  .cv-page .xp-steps-toggle {
    width: var(--m-hit);
    height: var(--m-hit);
    margin: -12px;
  }

  .cv-upnext-card .xp-endbox-x.xp-ib {
    width: var(--m-hit);
    height: var(--m-hit);
    top: 0;
    right: 0;
  }
}

@media (hover: none) {
  .cv-pt[data-s="unmade"] .cv-act {
    opacity: 1;
  }
}

@media (prefers-reduced-motion: reduce) {
  .cv-dot {
    animation: none;
  }

  .cv-grp-h .cv-chev {
    transition: none;
  }

  .cv-pop, .cv-sheet {
    transition: none;
    animation: none;
  }
}

.lx-list {
  animation: lx-in var(--dur-standard) var(--ease-standard);
}

@keyframes lx-in {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

.lx-filter {
  gap: 6px;
  margin: 0 0 22px;
  display: grid;
}

.lx-filter .lx-chips {
  margin: 0;
}

.lx-filter .lx-chips + .lx-chips {
  border-left: 2px solid var(--line);
  padding-left: 12px;
}

.lx-cont {
  background: var(--panel);
  box-shadow: inset 0 0 0 1px var(--line);
  border-radius: 2px;
  grid-template-columns: minmax(0, 300px) minmax(0, 1fr);
  align-items: center;
  gap: 20px;
  margin: 0 0 28px;
  padding: 14px;
  display: grid;
  position: relative;
}

.lx-cont:hover {
  box-shadow: inset 0 0 0 1px var(--ink-3);
}

.lx-lab {
  letter-spacing: .04em;
  text-transform: uppercase;
  color: var(--accent);
  margin: 0 0 4px;
  font-size: 11.5px;
  font-weight: 600;
}

.lx-cont-title {
  font-family: var(--read);
  text-wrap: balance;
  margin: 0 0 6px;
  font-size: 24px;
  font-weight: 400;
  line-height: 1.15;
}

.lx-cont-meta {
  color: var(--ink-2);
  margin: 0;
  font-size: 13px;
}

.lx-row {
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  margin-top: 12px;
  display: flex;
}

.lx-resume {
  background: var(--accent);
  color: var(--on-accent);
  border-radius: 2px;
  align-items: center;
  gap: 7px;
  padding: 7px 13px;
  font-size: 13px;
  font-weight: 500;
  display: inline-flex;
}

.lx-group {
  margin: 0 0 12px;
  font-size: 13px;
  font-weight: 600;
}

.lx-group span {
  color: var(--ink-2);
  margin-left: 8px;
  font-weight: 400;
}

.lx-grid {
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 330px), 1fr));
  gap: 18px;
  margin: 0 0 30px;
  display: grid;
}

.lx-card {
  background: var(--panel);
  min-width: 0;
  box-shadow: inset 0 0 0 1px var(--line);
  border-radius: 2px;
  flex-direction: column;
  display: flex;
  position: relative;
}

.lx-card:hover {
  box-shadow: inset 0 0 0 1px var(--ink-3);
}

.lx-card:hover .lx-tag {
  color: var(--ink);
  border-color: var(--accent);
}

.lx-body {
  flex-direction: column;
  flex: 1;
  gap: 7px;
  padding: 12px 14px;
  display: flex;
}

.lx-title {
  font-family: var(--read);
  text-wrap: balance;
  overflow-wrap: anywhere;
  margin: 0;
  font-size: 18px;
  font-weight: 400;
  line-height: 1.2;
}

.lx-link {
  color: inherit;
  text-decoration: none;
}

.lx-link:after {
  content: "";
  z-index: 1;
  position: absolute;
  inset: 0;
}

.lx-link:focus-visible {
  outline: none;
}

.lx-link:focus-visible:after {
  outline: var(--focus-ring);
  outline-offset: 2px;
}

.lx-ft {
  color: var(--ink-2);
  justify-content: space-between;
  gap: 8px;
  margin-top: auto;
  font-size: 11.5px;
  display: flex;
}

.lx-ft b {
  text-overflow: ellipsis;
  min-width: 0;
  color: var(--ink-2);
  white-space: nowrap;
  font-weight: 500;
  overflow: hidden;
}

.lx-ft b.acc {
  color: var(--accent);
}

.lx-ft b.warn {
  color: var(--warn);
}

.lx-more {
  z-index: 2;
  background: var(--panel);
  box-shadow: inset 0 0 0 1px var(--line);
  opacity: 0;
  transition: opacity var(--dur-quick) var(--ease-standard);
  position: absolute;
  top: 6px;
  right: 6px;
}

.lx-card:hover .lx-more, .lx-more:focus-visible, .lx-more[data-state="open"] {
  opacity: 1;
}

.lx-more:focus-visible {
  outline: var(--focus-ring);
}

@media (hover: none) {
  .lx-more {
    opacity: 1;
  }
}

.lx-shared {
  color: var(--accent);
  white-space: nowrap;
  flex-shrink: 0;
  align-items: center;
  gap: 3px;
  font-weight: 500;
  display: inline-flex;
}

.lx-shared svg {
  width: 11px;
  height: 11px;
}

.lx-ft-end {
  align-items: center;
  gap: 8px;
  min-width: 0;
  display: inline-flex;
}

.lx-share-link {
  box-sizing: border-box;
  width: 100%;
  box-shadow: inset 0 0 0 1px var(--rule);
  font-family: var(--ui);
  color: var(--ink);
  text-overflow: ellipsis;
  background: none;
  border: 0;
  border-radius: 2px;
  margin: 0 0 4px;
  padding: 5px 8px;
  font-size: 12px;
  display: block;
}

.lx-share-link:focus-visible {
  outline: var(--focus-ring);
}

.lx-share .row .lx-share-stop {
  margin-right: auto;
}

.lx-share-quotes {
  color: var(--ink-2);
}

.lx-share-link + .lx-share-quotes {
  margin-top: 12px;
}

.lx-share-quotes strong {
  color: var(--ink);
  font-weight: 600;
}

.lx-tag {
  border: 1px solid var(--line);
  max-width: 100%;
  color: var(--ink-2);
  white-space: nowrap;
  text-overflow: ellipsis;
  border-radius: 2px;
  align-self: flex-start;
  align-items: center;
  gap: 4px;
  padding: 2px 6px;
  font-size: 11px;
  display: inline-flex;
  overflow: hidden;
}

.lx-tag > span {
  text-overflow: ellipsis;
  overflow: hidden;
}

.lx-tag b {
  color: var(--ink);
  flex-shrink: 0;
  font-weight: 500;
}

.lx-tag .ic {
  width: 10px;
  height: 10px;
  color: var(--accent);
  flex-shrink: 0;
}

.lx-poster {
  border-bottom: 1px solid var(--line);
  position: relative;
  overflow: hidden;
}

.lx-cont .lx-poster {
  border: 1px solid var(--line);
}

.lx-poster .xp-box {
  pointer-events: none;
}

.lx-poster .xp-slide, .lx-poster .xp-tc-brand, .lx-poster .xp-tc-text, .lx-poster .xp-tc-question, .lx-poster .xp-tc-meta {
  animation: none;
}

.lx-poster.is-failed .xp-tc-text, .lx-poster.is-failed .xp-tc-brand {
  opacity: .45;
}

.lx-dur {
  background: var(--media-badge);
  color: var(--on-media);
  font-variant-numeric: tabular-nums;
  border-radius: 2px;
  padding: 1px 6px;
  font-size: 11px;
  position: absolute;
  bottom: 7px;
  right: 7px;
}

.lx-making {
  background: var(--accent-soft);
  color: var(--accent-strong);
  border-radius: 2px;
  align-items: center;
  gap: 6px;
  padding: 2px 7px;
  font-size: 11px;
  display: inline-flex;
  position: absolute;
  bottom: 7px;
  right: 7px;
}

.lx-badge {
  background: var(--media-badge);
  color: var(--on-media);
  border-radius: 2px;
  padding: 1px 6px;
  font-size: 11px;
  font-weight: 500;
  position: absolute;
  top: 7px;
  left: 7px;
}

.lx-dot {
  background: currentColor;
  border-radius: 50%;
  width: 6px;
  height: 6px;
  animation: 1.4s ease-in-out infinite lx-breathe;
}

@keyframes lx-breathe {
  0%, 100% {
    opacity: .35;
  }

  50% {
    opacity: 1;
  }
}

.lx-prog {
  height: 3px;
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
}

.lx-prog i {
  background: var(--accent);
  height: 100%;
  display: block;
}

.lx-empty {
  max-width: 520px;
  color: var(--ink-2);
  padding: 28px 0;
  font-size: 14px;
}

.lx-empty p {
  margin: 0 0 12px;
}

.lx-empty-link {
  color: var(--accent);
  font-weight: 500;
  text-decoration: none;
}

.lx-empty-link:hover {
  text-decoration: underline;
}

.lx-placeholder {
  --ph: var(--surface-board);
}

.lx-ph-group {
  background: var(--ph);
  border-radius: 3px;
  width: 120px;
  height: 12px;
  margin: 2px 0 14px;
}

.lx-ph-card {
  background: var(--panel);
  box-shadow: inset 0 0 0 1px var(--line);
  border-radius: 2px;
}

.lx-ph-poster {
  aspect-ratio: 16 / 9;
  background: var(--ph);
}

.lx-ph-lines {
  gap: 9px;
  padding: 12px 14px 14px;
  display: grid;
}

.lx-ph-line {
  background: var(--ph);
  border-radius: 3px;
  height: 10px;
}

.lx-ph-line.is-short {
  width: 46%;
}

.lx-ph-line.is-tiny {
  width: 30%;
}

@media (max-width: 640px) {
  .lx-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .lx-cont {
    grid-template-columns: minmax(0, 1fr);
    gap: 12px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .lx-list {
    animation: none;
  }

  .lx-dot {
    opacity: 1;
    animation: none;
  }
}

.ob-welcome {
  background: var(--surface-page);
  min-height: 100dvh;
  color: var(--text);
  place-items: center;
  padding: 72px 24px 40px;
  font-size: 14px;
  line-height: 1.5;
  display: grid;
  position: relative;
}

.ob-welcome-top {
  position: absolute;
  top: 20px;
  left: 24px;
}

.ob-namebox {
  flex-direction: column;
  gap: 18px;
  width: min(500px, 100%);
  display: flex;
}

.ob-namebox h1 {
  font-family: var(--read);
  letter-spacing: -.015em;
  margin: 0;
  font-size: 40px;
  font-weight: 400;
  line-height: 1.06;
}

.ob-welcome .field-control {
  min-height: 42px;
  padding: 9px 12px;
  font-size: 14.5px;
}

.ob-welcome .field-control:focus {
  outline: 2px solid var(--accent);
  outline-offset: -1px;
  border-color: #0000;
}

.ob-welcome .field-control[aria-invalid="true"] {
  border-color: var(--warn);
}

.ob-welcome .ob-big {
  min-height: 54px;
  font-family: var(--read);
  font-size: 24px;
}

.ob-hint-warn {
  color: var(--warn);
}

.ob-other {
  margin-top: 8px;
}

.ob-tz {
  color: var(--text-muted);
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  font-size: 12.5px;
  display: flex;
}

.ob-tz-change {
  font-size: 12.5px;
}

.ob-tz-pick select {
  min-height: 34px;
  padding: 4px 8px;
  font-size: 13px;
}

.ob-row {
  flex-wrap: wrap;
  align-items: center;
  gap: 14px;
  display: flex;
}

.ob-welcome .button {
  border-radius: 2px;
  min-height: 40px;
  padding: 8px 16px;
  font-size: 14px;
}

.ob-welcome .button:hover:not(:disabled) {
  background: var(--accent-strong);
}

.ob-welcome .button:disabled {
  cursor: default;
  opacity: .45;
}

.ob-later {
  color: var(--text-muted);
  font-size: 12.5px;
}

.ob-welcome .notice {
  padding: 10px 12px;
  font-size: 13px;
}

.ob-welcome .notice strong {
  margin: 0 .25em 0 0;
