}

@media (max-width: 699.98px) {
  .ob-welcome {
    flex-direction: column;
    justify-content: flex-start;
    align-items: stretch;
    padding: 18px 20px 28px;
    display: flex;
  }

  .ob-welcome-top {
    margin-bottom: 18px;
    position: static;
  }

  .ob-namebox {
    width: 100%;
  }

  .ob-namebox h1 {
    font-size: 32px;
    line-height: 1.08;
  }

  .ob-welcome .ob-big {
    min-height: 52px;
    font-size: 22px;
  }

  .ob-welcome .auth-chip {
    border-radius: 18px;
    padding: 9px 13px;
    font-size: 13.5px;
  }

  .ob-row {
    flex-direction: column;
    align-items: stretch;
    gap: 12px;
  }

  .ob-welcome .ob-continue {
    width: 100%;
    min-height: 46px;
  }

  .ob-later {
    text-align: center;
  }
}

.ob-ws {
  color: var(--text);
  position: relative;
}

.ob-graph .map-waiting button:disabled {
  cursor: default;
  opacity: .45;
}

.ob-xcard {
  animation: ob-fade .35s var(--ease-standard) both;
}

.ob-head {
