  border: 1px solid var(--rule);
  background: var(--surface-panel);
  font-family: var(--read);
  border-radius: 6px;
  margin: 0;
  padding: 8px 10px;
  font-size: 15px;
}

.ob-edit-open {
  align-self: flex-start;
}

.ob-edit {
  flex-direction: column;
  gap: 10px;
  display: flex;
}

.ob-edit-row {
  flex-direction: column;
  gap: 6px;
  display: flex;
}

.ob-edit-row .field-label {
  font-size: 12px;
}

.ob-edit .auth-chip[aria-pressed="true"] {
  background: var(--text);
  color: var(--on-ink);
  box-shadow: none;
}

.ob-edit-acts {
  align-items: center;
  gap: 12px;
  display: flex;
}

.ob-next {
  animation: ob-fade .35s var(--ease-standard) both;
  flex-direction: column;
  gap: 8px;
  display: flex;
}

.ob-nc {
  width: 100%;
  color: var(--text);
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition: border-color var(--dur-quick) ease, transform var(--dur-standard) var(--ease-entrance);
  align-items: center;
  gap: 12px;
  padding: 11px 12px;
  display: flex;
}

.ob-nc:hover:not(:disabled) {
  border-color: var(--text-decor);
  transform: translateX(2px);
}

.ob-nc:focus-visible {
  outline: var(--focus-ring);
  outline-offset: 2px;
}

.ob-nc .ico {
  background: var(--surface-page);
  width: 32px;
  height: 32px;
  box-shadow: inset 0 0 0 1px var(--rule);
  color: var(--accent);
  border-radius: 6px;
  flex-shrink: 0;
  place-items: center;
  display: grid;
}

.ob-nc .ico svg {
  width: 17px;
  height: 17px;
}

.ob-nc .tx {
  flex: 1;
  min-width: 0;
}

.ob-nc .tx b {
  font-size: 13.5px;
  font-weight: 500;
  display: block;
}

.ob-nc .tx span {
  color: var(--text-muted);
  font-size: 12px;
}

.ob-nc .ar {
  color: var(--text-muted);
}

.ob-look {
  align-self: flex-start;
  margin-top: 2px;
}

.ob-err {
  border: 1px solid var(--warn);
  background: var(--warn-soft);
  border-radius: 8px;
  flex-direction: column;
  gap: 8px;
  padding: 12px;
  font-size: 13px;
  display: flex;
}

.ob-err p {
  margin: 0;
}

.ob-err b {
  color: var(--warn);
  font-weight: 600;
}

.ob-err-acts {
  flex-wrap: wrap;
  gap: 8px;
  display: flex;
}

@keyframes ob-fade {
  from {
    opacity: 0;
    transform: translateY(4px);
  }

  to {
    opacity: 1;
    transform: none;
  }
}

@media (max-width: 980px) and (min-width: 700px) {
  .ob-graph {
    height: max(520px, 100dvh - 140px);
    margin-right: -24px;
  }

  .ob-graph .graph-canvas {
    height: 100%;
    min-height: 0;
  }

  .ob-graph .gnav, .ob-graph .gtop {
    padding-right: 432px;
  }

  .ob-graph .cpwrap {
    pointer-events: none;
    width: 420px;
    height: auto;
    margin: 0;
    position: absolute;
    top: 0;
    bottom: 0;
    right: 0;
  }

  .ob-graph .cp {
    max-height: none;
    position: absolute;
    inset: 12px;
  }
}

@media (max-width: 699.98px) {
  .ob-ws {
    margin: 0 calc(-1 * var(--m-gutter)) -28px;
    flex-direction: column;
    display: flex;
  }

  .ob-graph {
    flex-direction: column;
    flex: auto;
    height: auto;
    min-height: 0;
    margin: 0;
    padding: 0;
    display: flex;
  }

  .ob-graph .graph-canvas {
    flex: 0 0 52%;
    height: auto;
    min-height: 0;
    padding: 0 12px;
  }

  .ob-graph .gnav {
    flex-wrap: nowrap;
    min-height: 22px;
    margin: 0;
  }

  .ob-graph .gbtns, .ob-graph .legend {
    display: none;
  }

  .ob-graph .gtop {
    margin: 0 0 6px;
  }

  .ob-graph .map-corner {
    bottom: 4px;
    left: auto;
    right: 0;
  }

  .ob-graph .cpwrap {
    flex: auto;
    width: auto;
    height: auto;
    min-height: 0;
    margin: 0;
    position: relative;
    inset: auto;
  }

  .ob-graph .cp {
    max-height: none;
    box-shadow: var(--shadow-float);
    border-radius: 14px 14px 0 0;
    position: absolute;
    inset: 0;
  }

  .ob-head {
    gap: 9px;
    padding: 10px 14px 9px;
  }

  .ob-mark {
    border-radius: 5px;
    width: 22px;
    height: 22px;
    font-size: 13px;
  }

  .ob-head-t b {
    font-size: 13px;
    line-height: 1.2;
  }

  .ob-head-t span {
    font-size: 11.5px;
    line-height: 1.2;
  }

  .ob-body {
    overscroll-behavior: contain;
    padding: 14px 14px 16px;
  }

  .ob-ws .cp-comp {
    padding: 8px 12px 10px;
  }

  .ob-ws .cp-comp textarea {
    min-height: 24px;
    max-height: 26px;
  }

  .ob-qopt {
    padding: 8px 12px;
  }

  .ob-qt {
    font-size: 17px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .ob-qcard, .ob-prop, .ob-mem, .ob-next, .ob-xcard {
    animation: none;
  }

  .ob-qopt, .ob-nc {
    transition: none;
  }
}

.td {
  grid-template-columns: minmax(0, 1fr) 300px;
  align-items: start;
  gap: 52px;
  max-width: 1180px;
  display: grid;
}

.td a:not(.button) {
  color: inherit;
}

.td-head {
  justify-content: space-between;
  align-items: baseline;
  gap: 20px;
  margin: 0 0 22px;
  display: flex;
}

.td-head h1 {
  letter-spacing: -.01em;
  margin: 0;
  font-size: 22px;
  font-weight: 600;
}

.td-head h1 span {
  color: var(--ink-2);
  margin-left: 8px;
  font-weight: 400;
}

.td-head p {
  min-width: 5ch;
  color: var(--ink-2);
  font-variant-numeric: tabular-nums;
  text-align: right;
  margin: 0;
  font-size: 13px;
}

.td-row {
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  display: flex;
}

.td a.button {
  text-decoration: none;
}

.td-top {
  grid-template-columns: minmax(0, 1.6fr) minmax(220px, 1fr);
  align-items: stretch;
  gap: 22px;
  margin: 0 0 30px;
  display: grid;
}

.td-next {
  border-left: 2.5px solid var(--accent);
  background: var(--panel);
  animation: tdIn var(--dur-standard) var(--ease-entrance);
  flex-direction: column;
  justify-content: center;
  padding: 16px 20px 15px;
  display: flex;
}

.td-next.is-first {
  border-left-color: var(--myfocus-ink);
}

.td-k {
  color: var(--ink-2);
  margin: 0 0 5px;
  font-size: 11.5px;
  font-weight: 500;
}

.td-n {
  font-family: var(--read);
  text-wrap: balance;
  margin: 0 0 8px;
  font-size: 20.5px;
  font-weight: 500;
  line-height: 1.25;
}

.td-m {
  color: var(--ink-2);
  margin: 0 0 14px;
  font-size: 13px;
  line-height: 1.45;
}

.td-m b {
  color: var(--ink);
  font-weight: 500;
}

.td-bar {
  background: var(--line);
  max-width: 420px;
  height: 2px;
  margin: 0 0 10px;
  position: relative;
}

.td-bar i {
  background: var(--accent);
  position: absolute;
  inset: 0 auto 0 0;
}

.td-after {
  color: var(--ink-2);
  margin: 12px 0 0;
  font-size: 12.5px;
  line-height: 1.5;
}

.td-after a {
  -webkit-text-decoration-color: var(--line);
  text-decoration-color: var(--line);
  text-underline-offset: 3px;
}

.td-after a:hover {
  color: var(--accent);
  text-decoration-color: currentColor;
}

.td-after kbd {
  font: inherit;
  border: 1px solid var(--line);
  border-radius: 2px;
  padding: 0 4px;
  font-size: 11.5px;
}

.td-later {
  border: 1px dashed var(--line);
  color: var(--ink-2);
  align-items: center;
  margin: 0;
  padding: 14px 18px;
  font-size: 13px;
  display: flex;
}

.td-later button {
  all: unset;
  cursor: pointer;
  color: var(--ink);
  text-underline-offset: 3px;
  margin-left: 6px;
  text-decoration: underline;
}

.td-later button:focus-visible {
  outline: var(--focus-ring);
  outline-offset: 2px;
}

.td-h {
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
  margin: 0 0 10px;
  display: flex;
}

.td-h h2 {
  text-transform: uppercase;
  letter-spacing: .05em;
  color: var(--ink-2);
  margin: 0;
  font-size: 11.5px;
  font-weight: 600;
}

.td-h.is-plain h2 {
  text-transform: none;
  letter-spacing: normal;
  color: var(--ink);
  font-size: 13px;
}

.td-h > span {
  color: var(--ink-2);
  font-size: 12px;
}

.td-empty {
  color: var(--ink-2);
  margin: 0;
  font-size: 13px;
  line-height: 1.5;
}

.td-more {
  color: var(--ink-2);
  margin-top: 8px;
  font-size: 12.5px;
  text-decoration: none;
  display: inline-block;
}

.td-more:hover {
  color: var(--accent);
}

.td-focus-wrap {
  border-left: 1px solid var(--line);
  padding: 4px 0 4px 18px;
}

.td-focus-wrap .td-h {
  margin-bottom: 6px;
}

.td-focus {
  margin: 0;
  padding: 0;
  list-style: none;
}

.td-focus-row {
  grid-template-columns: 14px minmax(0, 1fr);
  align-items: baseline;
  gap: 8px;
  padding: 6px 0;
  text-decoration: none;
  display: grid;
}

.td-focus-row:hover b {
  color: var(--accent);
}

.td-focus-row:focus-visible {
  outline: var(--focus-ring);
  outline-offset: 2px;
}

.td-star {
  color: var(--myfocus-ink);
  font-size: 11px;
}

.td-focus-name {
  gap: 2px;
  min-width: 0;
  display: grid;
}

.td-focus-name b {
  white-space: nowrap;
  text-overflow: ellipsis;
  transition: color var(--dur-quick) ease;
  font-weight: 500;
  overflow: hidden;
}

.td-focus-state {
  flex-wrap: wrap;
  align-items: baseline;
  gap: 6px;
  display: inline-flex;
}

.td-focus-state .state {
  font-size: 11.5px;
}

.td-wait {
  color: var(--ink-2);
  font-size: 11.5px;
}

.td-wait:before {
  content: "·";
  margin-right: 6px;
}

.td-wait.is-ghost {
  color: var(--ghost-ink);
}

.td-compass {
  margin: 0 0 28px;
}

.td-narrative {
  border-left: 2px solid var(--line);
  padding: 2px 0 2px 16px;
}

.td-narrative p {
  max-width: 68ch;
  font-family: var(--read);
  margin: 0 0 8px;
  font-size: 16px;
  line-height: 1.55;
}

.td-narrative em {
  color: var(--accent);
  font-style: italic;
}

.td-narrative .td-sub {
  font-family: var(--ui);
  color: var(--ink-2);
  margin: 8px 0 0;
  font-size: 12.5px;
  line-height: 1.5;
}

.td-err {
  border: 1px solid var(--line);
  background: var(--panel);
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  padding: 10px 12px 10px 14px;
  display: flex;
}

.td-err p {
  color: var(--ink-2);
  margin: 0;
  font-size: 13px;
}

.td-err b {
  color: var(--warn);
  font-weight: 500;
}

.td-err .button {
  white-space: nowrap;
}

.td-rail .td-err, .td-focus-wrap .td-err {
  flex-direction: column;
  align-items: flex-start;
}

.td-rail {
  flex-direction: column;
  height: calc(100dvh - 88px);
  min-height: 520px;
  display: flex;
  position: sticky;
  top: 0;
}

.td-strip {
  gap: 3px;
  margin: 0 0 10px;
  display: flex;
}

.td-strip button {
  all: unset;
  text-align: center;
  color: var(--ink-2);
  cursor: pointer;
  border-radius: 3px;
  flex: 1;
  padding: 5px 0 7px;
  font-size: 11px;
  line-height: 1.2;
  position: relative;
}

.td-strip button:hover:not(:disabled):not(.is-on) {
  background: var(--hover-fill);
}

.td-strip button:focus-visible {
  outline: var(--focus-ring);
  outline-offset: 1px;
}

.td-strip button:disabled {
  cursor: default;
  opacity: .55;
}

.td-strip b {
  color: var(--ink);
  margin-top: 1px;
  font-size: 14px;
  font-weight: 500;
  display: block;
}

.td-strip i {
  background: var(--accent);
  border-radius: 50%;
  width: 4px;
  height: 4px;
  margin-left: -2px;
  position: absolute;
  bottom: 2px;
  left: 50%;
}

.td-strip .is-on {
  background: var(--ink);
  color: var(--status-1);
}

.td-strip .is-on b {
  color: var(--on-ink);
}

.td-strip .is-on i {
  background: var(--on-ink);
}

.td-dayline {
  color: var(--ink-2);
  margin: 0 0 8px;
  font-size: 12.5px;
}

.td-dayline b {
  color: var(--ink);
  font-weight: 500;
}

.td-cal {
  flex-direction: column;
  flex: 1;
  min-height: 0;
  font-size: 13px;
  display: flex;
  overflow-y: auto;
}

.td-cal-row {
  flex: 1 0 auto;
  grid-template-columns: 44px minmax(0, 1fr);
  min-height: 26px;
  display: grid;
}

.td-cal-t {
  border-right: 1px solid var(--line);
  text-align: right;
  color: var(--ink-2);
  font-variant-numeric: tabular-nums;
  padding: 4px 10px 0 0;
  font-size: 11.5px;
}

.td-cal-c {
  align-content: start;
  gap: 4px;
  min-width: 0;
  padding: 3px 0 3px 12px;
  display: grid;
  position: relative;
}

.td-cal-now {
  border-top: 1.5px solid var(--warn);
  height: 0;
  position: absolute;
  left: -4px;
  right: 0;
}

.td-cal-now:before {
  content: "";
  background: var(--warn);
  border-radius: 50%;
  width: 7px;
  height: 7px;
  position: absolute;
  top: -4.5px;
  left: -3px;
}

.td-ev {
  border-left: 2px solid var(--accent);
  padding: 2px 0 2px 9px;
  line-height: 1.35;
  text-decoration: none;
  display: block;
}

.td-ev small {
  color: var(--ink-2);
  font-size: 11.5px;
  display: block;
}

.td-ev:hover {
  color: var(--accent);
}

.td-ev:focus-visible {
  outline: var(--focus-ring);
  outline-offset: 2px;
}

.td-ev.is-saved {
  border-left-color: var(--ink-3);
}

.td-ev.is-copilot {
  border-left: 2px dashed var(--ghost);
}

.td-plan-later {
  border-left: 2px dashed var(--line);
  color: var(--ink-2);
  margin: 10px 0 0;
  padding: 4px 0 4px 10px;
  font-size: 12px;
}

.td-placeholder {
  --ph: var(--surface-board);
}

.td-ph {
  height: 11px;
  margin: 0 0 10px;
  display: block;
}

.td-ph.is-title {
  height: 20px;
}

.td-ph-date {
  vertical-align: -1px;
  width: 150px;
  height: 16px;
  margin-left: 8px;
  display: inline-block;
}

.td-ph-btn {
  width: 150px;
  height: 34px;
  display: block;
}

.td-ph-btn.is-wide {
  width: 180px;
}

.td-ph-strip {
  height: 44px;
  margin: 0 0 14px;
  display: block;
}

.td-ph-cal {
  flex: 1;
  display: block;
}

@keyframes tdIn {
  from {
    opacity: 0;
    transform: translateY(var(--enter-travel));
  }
}

@media (max-width: 1180px) {
  .td-top {
    grid-template-columns: minmax(0, 1fr);
  }

  .td-focus-wrap {
    border-left: 0;
    padding-left: 0;
  }
}

@media (max-width: 980px) {
  .td {
    grid-template-columns: minmax(0, 1fr);
    gap: 30px;
  }

  .td-rail {
    height: auto;
    min-height: 0;
    position: static;
  }

  .td-cal {
    max-height: none;
    overflow: visible;
  }
}

@media (max-width: 699.98px), (pointer: coarse) {
  .td-focus-row {
    min-height: var(--m-hit);
    align-items: center;
  }

  .td-strip button {
    min-height: var(--m-hit);
  }
}

@media (max-width: 699.98px) {
  .td-head h1 {
    font-size: 24px;
  }

  .td-head h1 span {
    margin: 2px 0 0;
    font-size: 15px;
    display: block;
  }

  .td-next .td-row .button:not(.button-link) {
    min-height: var(--m-hit);
    flex: 100%;
  }

  .td-cal-row:not(:has(.td-ev)):not(:has(.td-cal-now)) {
    display: none;
  }

  .td-cal-row {
    min-height: 30px;
  }
}

