  align-items: center;
  gap: 10px;
  margin-top: 26px;
  display: flex;
}

.xp-made .button {
  min-height: 40px;
  transition: background var(--dur-quick) var(--ease-standard), box-shadow var(--dur-quick) var(--ease-standard);
  padding: 8px 18px;
  font-size: 14px;
  text-decoration: none;
}

.xp-made .button:hover {
  background: var(--accent-strong);
}

.xp-made .button-quiet:hover {
  background: var(--hover-fill);
  box-shadow: inset 0 0 0 1px var(--ink-3);
}

.xp-made .button:focus-visible {
  outline: var(--focus-ring);
  outline-offset: 2px;
}

.xp-made-note {
  color: var(--ink-2);
  margin: 14px 0 0;
  font-size: 12.5px;
}

.xp-made-cues {
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
  margin: 0;
  padding: 0;
  list-style: none;
  display: grid;
}

.xp-made-cue {
  background: var(--panel);
  box-shadow: inset 0 0 0 1px var(--line);
  border-radius: 3px;
  align-content: start;
  gap: 12px;
  padding: 15px 17px;
  display: grid;
}

.xp-made-pic {
  aspect-ratio: 13 / 9;
  background: var(--board);
  border-radius: 2px;
  width: 100%;
  height: auto;
  display: block;
}

.xp-made-label {
  color: var(--ink-2);
  letter-spacing: .04em;
  text-transform: uppercase;
  font-size: 11.5px;
  font-weight: 600;
  display: block;
}

.xp-made-line {
  color: var(--ink);
  font-family: var(--read);
  margin: 4px 0 0;
  font-size: 17px;
  line-height: 1.35;
}

.xp-made-line em {
  color: var(--accent);
}

.xp-made-foot {
  border-top: 1px solid var(--line);
  color: var(--ink-2);
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 6px 16px;
  padding: 14px 0 22px;
  font-size: 12.5px;
  display: flex;
}

.xp-made-foot a {
  color: var(--ink-2);
  text-underline-offset: 3px;
}

.xp-made-foot a:hover {
  color: var(--ink);
}

.mw-lk {
  stroke: var(--ink-3);
  stroke-opacity: .55;
  stroke-width: 1px;
}

.mw-lk.mw-g {
  stroke: var(--ghost);
  stroke-opacity: 1;
  stroke-dasharray: 3 3;
  stroke-width: 1.1px;
}

.mw-nd.mw-s0 {
  fill: var(--paper);
  stroke: var(--ink-3);
  stroke-width: 1px;
}

.mw-nd.mw-s1 {
  fill: var(--status-1);
  stroke: var(--status-1);
}

.mw-nd.mw-s2 {
  fill: var(--status-2);
  stroke: var(--status-2);
}

.mw-nd.mw-g {
  fill: var(--ghost-soft);
  stroke: var(--ghost);
  stroke-width: 1.2px;
  stroke-dasharray: 2.5 2.5;
}

.mw-ctr {
  fill: var(--ink);
  stroke: var(--board);
  stroke-width: 2px;
}

.mw-lbl {
  fill: var(--ink);
  font-family: var(--read);
  text-anchor: middle;
  paint-order: stroke;
  stroke: var(--board);
  stroke-width: 4px;
  stroke-linejoin: round;
  font-size: 10.5px;
}

.mw-lbl.mw-c {
  font-size: 12px;
  font-weight: 500;
}

.mw-lbl.mw-g {
  fill: var(--ghost-ink);
  font-style: italic;
}

.mw-panel {
  fill: var(--panel);
  stroke: var(--line);
}

.mw-cover {
  fill: var(--cover-paper);
}

.mw-cover-ink {
  fill: var(--cover-ink);
  font-family: var(--read);
}

.mw-ink {
  fill: var(--ink);
}

.mw-ink2 {
  fill: var(--ink-2);
}

.mw-read {
  font-family: var(--read);
}

.mw-ui {
  font-family: var(--ui);
}

.mw-quote {
  fill: var(--quote-paper);
  stroke: var(--quote-rule);
}

.mw-quote-bar {
  fill: var(--quote-rule);
}

.mw-accent {
  fill: var(--accent);
}

.mw-mark {
  fill: var(--ink);
}

.mw-mark-s {
  fill: var(--panel);
  font-family: var(--read);
}

.mw-cap {
  fill: var(--caption-bg);
}

.mw-cap-ink {
  fill: var(--caption-ink);
  font-family: var(--ui);
}

@media (max-width: 1023px) {
  .xp-shared-first {
    padding-block: 12px 28px;
  }

  .xp-made-body {
    grid-template-columns: minmax(0, 1fr);
    gap: 32px;
  }
}

@media (max-width: 980px) {
  .xp-shared-first {
    padding-inline: 24px;
  }

  .xp-made {
    margin-inline: 24px;
  }
}

@media (max-width: 639px) {
  .xp-made {
    padding-top: 18px;
  }

  .xp-made-body {
    gap: 28px;
    padding: 26px 0 40px;
  }

  .xp-made h2 {
    font-size: 30px;
  }

  .xp-made-lead {
    font-size: 16px;
  }

  .xp-made-acts {
    grid-template-columns: 1fr 1fr;
    display: grid;
  }

  .xp-made .button {
    min-height: 44px;
  }

  .xp-made-cues {
    grid-template-columns: minmax(0, 1fr);
    gap: 10px;
  }

  .xp-made-cue {
    grid-template-columns: 112px minmax(0, 1fr);
    align-items: center;
    gap: 14px;
    padding: 12px;
  }

  .xp-made-line {
    font-size: 16px;
  }
}

@media (max-width: 560px) {
  .xp-shared-first {
    padding-inline: 18px;
  }

  .xp-made {
    margin-inline: 18px;
  }
}

@media (pointer: coarse) {
  .destination-tab {
    min-height: var(--m-hit);
    box-sizing: border-box;
    align-items: center;
    display: inline-flex;
  }

  .button:not(.button-link) {
    min-height: var(--m-hit);
  }

  .button-link {
    position: relative;
  }

  .button-link:after {
    content: "";
    position: absolute;
    inset: -5px -4px;
  }

  .collection-more {
    min-width: var(--m-hit);
  }

  .lsearch input, .gtree-search input, .coll-form-card input[type="text"] {
    min-height: var(--m-hit);
    box-sizing: border-box;
  }

  .colls button {
    box-sizing: border-box;
    align-items: center;
    min-height: 36px;
    display: inline-flex;
  }

  .library-crumb a {
    margin: -13px 0;
    padding: 13px 0;
    display: inline-block;
  }

  .cf-crumb-button {
    margin: -13px 0;
    padding: 13px 2px;
  }

  .card-more {
    width: var(--m-hit);
    height: var(--m-hit);
    margin: -12px -12px -8px 0;
  }

  .mcard .topic-tag {
    margin: -16px 0;
    padding: 16px 0;
    display: inline-block;
  }

  .mcard .coll-kicker a {
    margin: -15px 0;
    padding: 15px 0;
  }

  .gtree-title {
    min-height: var(--m-hit);
  }

  .gtree-toggle {
    width: var(--m-hit);
    height: var(--m-hit);
    margin: 0 -15px;
  }

  .cp-grip {
    position: relative;
  }

  .cp-grip:before {
    content: "";
    position: absolute;
    inset: -24px 0 0;
  }
}

* {
  box-sizing: border-box;
}

html, body {
  min-height: 100%;
  margin: 0;
}

body {
  padding-left: env(safe-area-inset-left, 0px);
  padding-right: env(safe-area-inset-right, 0px);
  background: var(--surface-page);
  color: var(--text);
  font-family: var(--ui);
  letter-spacing: 0;
  -webkit-font-smoothing: antialiased;
  font-size: 14px;
  line-height: 1.45;
}

button, input, select, textarea {
  font: inherit;
}

a {
  color: inherit;
}

:focus-visible {
  outline: var(--focus-ring);
  outline-offset: 2px;
}

html {
  background: var(--surface-page);
}

html.theme-switching::view-transition-old(root) {
  animation-duration: .2s;
  animation-timing-function: var(--ease-standard);
}

html.theme-switching::view-transition-new(root) {
  animation-duration: .2s;
  animation-timing-function: var(--ease-standard);
}

@media (prefers-reduced-motion: reduce) {
  ::view-transition-group(*) {
    animation: none !important;
  }

  ::view-transition-old(*) {
    animation: none !important;
  }

  ::view-transition-new(*) {
    animation: none !important;
  }
}

::selection {
  background: var(--status-1);
  color: var(--ink);
}

.visually-hidden {
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  position: absolute !important;
}

